registerClass12ExerciseBanks("civics", {"1":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch1-exercise-1",1],["civ12-ch1-exercise-1",2]],"inline":1,"s":["1965ء کی جنگ کے بعد صدر ایوب خان نے بھارت کے ساتھ تاشقند امن معاہدہ کیا۔"],"c":2},{"q":[["civ12-ch1-exercise-1",3],["civ12-ch1-exercise-1",4]],"inline":1,"s":["ہماری سیاسی ثقافت کی بنیادیں عموماً غیر جمہوری ہیں؛ سیاست میں برداشت اور رواداری کا رواج عام کرنے کی ضرورت ہے۔"],"c":3},{"q":[["civ12-ch1-exercise-1",5],["civ12-ch1-exercise-1",6]],"inline":1,"s":["پارلیمانی نظام میں وزیرِاعظم اور وزرا پارلیمنٹ (قومی اسمبلی) کے سامنے جواب دہ ہوتے ہیں اور اس کا اعتماد کھو دیں تو عہدہ چھوڑنا پڑتا ہے۔"],"c":0},{"q":[["civ12-ch1-exercise-1",7],["civ12-ch1-exercise-1",8]],"inline":1,"s":["صدرِ پاکستان کسی قانونی یا آئینی مسئلے کی تشریح کے لیے سپریم کورٹ سے رائے (مشاورتی اختیار) طلب کر سکتے ہیں۔"],"c":3},{"q":[["civ12-ch1-exercise-1",9],["civ12-ch1-exercise-1",10]],"inline":1,"s":["فوج کی سب سے اہم ذمہ داری ملکی سرحدوں کی حفاظت اور اندرونی و بیرونی جارحیت سے دفاع ہے۔"],"c":2}],"objective":[{"q":[["civ12-ch1-text-25",4]],"s":["پارلیمانی","اسلامی جمہوریہ پاکستان جنوبی ایشیا کا ایک جمہوری اور وفاقی پارلیمانی ملک ہے۔"],"a":"پارلیمانی"},{"q":[["civ12-ch1-text-25",5]],"s":["چیف کمشنر کے صوبے (چیف کمشنری)","آزادی کے بعد بلوچستان کو چیف کمشنر کے صوبے کی حیثیت دی گئی؛ 1970ء میں اسے مکمل صوبے کا درجہ ملا۔"],"a":"چیف کمشنر کے صوبے (چیف کمشنری)"},{"q":[["civ12-ch1-text-25",6]],"s":["ایٹمی دھماکوں","28 مئی 1998ء کو ایٹمی دھماکے کر کے پاکستان کو دنیا کا ساتواں ایٹمی ملک بنا دیا گیا۔"],"a":"ایٹمی دھماکوں"},{"q":[["civ12-ch1-text-25",7]],"s":["عدلیہ کے احکامات پر عمل درآمد (نفاذ)","عدلیہ کے احکامات پر عمل درآمد کروانا بھی عاملہ (انتظامیہ) کی ذمہ داری ہے۔"],"a":"عدلیہ کے احکامات پر عمل درآمد (نفاذ)"},{"q":[["civ12-ch1-text-25",8]],"s":["مجرموں (حقائق)","خفیہ پولیس اپنے خفیہ ایجنٹوں کے ذریعے کسی واقعے سے پہلے حالات کا اندازہ لگاتی اور مجرموں تک پہنچنے کا اہم ذریعہ ہے۔"],"a":"مجرموں (حقائق)"},{"q":[["civ12-ch1-exercise-1",12]],"tf":"tf","s":["صحیح۔ برطانیہ میں نظامِ حکومت جمہوری نظریات پر قائم پارلیمانی جمہوریت ہے اور برصغیر کا نظام بھی اسی طرز پر تھا۔"],"c":0},{"q":[["civ12-ch1-exercise-1",13]],"tf":"tf","s":["غلط۔ ملک میں پہلے عام انتخابات 1970ء میں جنرل یحییٰ خان نے کروائے؛ 1988ء کے انتخابات غلام اسحاق خان نے کروائے تھے مگر وہ پہلے نہیں تھے۔"],"c":1},{"q":[["civ12-ch1-exercise-1",14]],"tf":"tf","s":["صحیح۔ جنرل ضیاء الحق نے 1985ء میں غیر جماعتی بنیادوں پر انتخابات کروائے۔"],"c":0},{"q":[["civ12-ch1-exercise-1",15]],"tf":"tf","s":["غلط۔ بنیادی انسانی حقوق کی محافظ عدلیہ (سپریم کورٹ اور ہائی کورٹس) ہے؛ کسی شہری کی درخواست پر اعلیٰ عدالت بنیادی حقوق کے منافی قانون کو کالعدم قرار دے سکتی ہے۔"],"c":1},{"q":[["civ12-ch1-exercise-1",16]],"tf":"tf","s":["صحیح۔ وزیرِاعظم قومی اسمبلی کی اکثریتی جماعت کا راہنما اور قائدِ ایوان ہوتا ہے۔"],"c":0},{"q":[["civ12-ch1-exercise-1",17]],"tf":"tf","s":["صحیح۔ پاکستان میں عاملہ صدر، وزیرِاعظم، کابینہ اور سرکاری ملازمین پر مشتمل ہے۔"],"c":0},{"q":[["civ12-ch1-exercise-1",18]],"tf":"tf","s":["غلط۔ بجٹ وزیرِ خزانہ قومی اسمبلی میں پیش کرتا ہے اور اس کی منظوری قومی اسمبلی (مقننہ) دیتی ہے، عدلیہ نہیں۔"],"c":1},{"q":[["civ12-ch1-exercise-1",19]],"tf":"tf","s":["غلط۔ پولیس کا محکمہ وزارتِ داخلہ اور صوبائی حکومتوں کی نگرانی میں کام کرتا ہے؛ وزیرِ دفاع کی نگرانی میں مسلح افواج کام کرتی ہیں۔"],"c":1},{"q":[["civ12-ch1-exercise-2",0]],"d":"civ12-ch1-match","s":["درست جوڑ:","رضاکار — شہری۔","عدالتِ — عالیہ۔","آڈیٹر — جنرل۔","آئینی — تشریحات۔","حکم — نامہ۔","میرٹ — اہلیت۔","جمہوری — اقدار۔"]}],"shortQuestions":[{"q":[["civ12-ch1-exercise-2",2]],"s":["پاکستان میں پہلی فوجی حکومت 27 اکتوبر 1958ء کو مسلح افواج کے سربراہ جنرل محمد ایوب خان نے قائم کی۔","انہوں نے آئینی حکومت ختم کر کے مارشل لا نافذ کیا اور 1956ء کا آئین منسوخ کر دیا؛ یہ دور مارچ 1969ء تک رہا۔"]},{"q":[["civ12-ch1-exercise-2",3]],"s":["تحریکِ استحقاق وہ تحریک ہے جو پارلیمنٹ کا کوئی رکن اس وقت پیش کرتا ہے جب اس کے یا ایوان کے استحقاق (حقوق، عزت و وقار) کو مجروح کیا جائے — مثلاً کسی سرکاری افسر کی بدسلوکی یا ایوان کو غلط معلومات دینا۔","ایوان اسے استحقاق کمیٹی کے سپرد کرتا ہے جو تحقیقات کر کے کارروائی کی سفارش کرتی ہے۔"]},{"q":[["civ12-ch1-exercise-2",4]],"s":["بجٹ (میزانیہ) حکومت کی ایک سال کی آمدنی اور اخراجات کا تخمینہ اور حساب ہے۔","مالی سال یکم جولائی سے 30 جون تک ہوتا ہے؛ مرکزی وزیرِ خزانہ بجٹ قومی اسمبلی میں پیش کرتا ہے اور قومی اسمبلی اسے کمی بیشی کے ساتھ یا اصل صورت میں منظور یا مسترد کر سکتی ہے۔"]},{"q":[["civ12-ch1-exercise-2",5]],"s":["سوموٹو (ازخود نوٹس) سے مراد یہ ہے کہ سپریم کورٹ کا چیف جسٹس کسی درخواست کے بغیر خود کسی معاملے کا نوٹس لے کر کارروائی کرے۔","یہ عموماً بنیادی حقوق کی خلاف ورزی یا عوامی اہمیت کے معاملات میں لیا جاتا ہے۔"]}],"longQuestions":[{"q":[["civ12-ch1-exercise-2",7]],"s":["پاکستان ایک جمہوری اور وفاقی پارلیمانی ملک ہے؛ 1956ء، 1962ء اور 1973ء کے آئینوں نے حکومت کے ڈھانچے کی تشکیل میں کردار ادا کیا۔ اس ڈھانچے کی بنیادیں یہ ہیں:","1۔ نظریہ: قیامِ پاکستان سے پہلے برصغیر کا نظام برطانوی پارلیمانی جمہوریت کے طرز پر تھا؛ پاکستان اسلامی نظریے پر بنا، قراردادِ مقاصد میں اللہ تعالیٰ کی حاکمیت تسلیم کی گئی اور تقریباً ہر آئین میں اسلام کو سرکاری مذہب قرار دیا گیا۔","2۔ تاریخ: پاکستان تاریخی طور پر ایک اکائی رہا ہے — وادیٔ سندھ کی تہذیب (2500–1700 ق م)، مغلیہ سلطنت اور پھر برطانوی ہند؛ دریائے سندھ کو پاکستان کی شہ رگ کہا جاتا ہے۔","3۔ ثقافت: پاکستان کثیر القومی ملک ہے جس میں پنجابی، سندھی، پختون اور بلوچ چار بنیادی لسانی و نسلی گروہ ہیں؛ اسی تنوع کی وجہ سے ملک کا ڈھانچہ وفاقی ہے اور صوبوں کو خود مختاری دی گئی ہے۔","4۔ اقدار: پاکستان میں روایتی، اسلامی اور مشرقی اقدار — دوستی، مہمان نوازی، مدد، ایثار اور اتحاد — موجود ہیں جو جمہوری نظام کو مضبوط بناتی ہیں۔"]},{"q":[["civ12-ch1-exercise-2",8]],"s":["پہلا جمہوری دور (1947–1958ء): مشکلات کے باوجود جمہوری حکومتیں رہیں اور 1956ء کا آئین بنا، مگر سیاسی عدم استحکام رہا۔","پہلا فوجی دور (1958–1969ء، ایوب خان): کامیابیاں — 1965ء کی جنگ، تاشقند معاہدہ، اسلام آباد دارالحکومت، سندھ طاس معاہدہ، صنعتی ترقی، بلدیاتی نظام، 1962ء کا آئین، آر سی ڈی؛ ناکامیاں — ایک فرد کا آئین، دولت چند ہاتھوں میں، سیاسی سرگرمیوں اور پریس پر پابندیاں۔ یحییٰ خان (1969–71ء) نے پہلے عام انتخابات کروائے مگر ملک دولخت ہوا۔","دوسرا جمہوری دور (1971–1977ء، ذوالفقار علی بھٹو): 1973ء کا متفقہ آئین، اسلامی سربراہی کانفرنس، قومیائی، اصلاحات، شناختی کارڈ، اسٹیل مل؛ پھر 1977ء میں جنرل ضیاء کا مارشل لا (1977–88ء): آٹھویں ترمیم، اسلامی قوانین، افغان جنگ۔","تیسرا جمہوری دور (1988–1999ء): بے نظیر اور نواز شریف کی حکومتیں، موٹروے، ایٹمی دھماکے؛ مگر بار بار اسمبلیوں کی برطرفی۔ جنرل مشرف کا فوجی دور (1999–2008ء): بلدیاتی نظام، آئینی ترامیم سے لامحدود اختیارات۔ 2008ء کے بعد جمہوری حکومتیں: عدلیہ کی بحالی، اٹھارویں ترمیم، بے نظیر انکم سپورٹ پروگرام۔","موازنہ: جمہوری ادوار میں عوامی شرکت، آئین کی بالادستی، آزاد پریس اور جواب دہی ہوتی ہے مگر حکومتیں عدم استحکام کا شکار رہیں؛ آمریت میں فیصلے تیز اور کچھ ترقی ہوئی مگر طاقت ایک فرد میں مرکوز، بنیادی حقوق اور سیاسی آزادی محدود رہی اور اداروں کو نقصان پہنچا۔ نتیجتاً جمہوریت ہی بہتر نظام ہے۔"]},{"q":[["civ12-ch1-exercise-2",9]],"s":["مقننہ (پارلیمنٹ) حکومت کا وہ ادارہ ہے جو قانون سازی کرتا ہے؛ پاکستان میں یہ قومی اسمبلی اور سینیٹ پر مشتمل ہے (مجلسِ شوریٰ)۔","1۔ قانون سازی: وفاقی فہرست کے موضوعات پر قوانین بنانا۔ 2۔ انتظامی: وزیرِاعظم کا انتخاب؛ وزیرِاعظم اور وزرا مقننہ کے سامنے جواب دہ؛ سوالات، تحاریک اور عدمِ اعتماد کے ذریعے حکومت پر کنٹرول۔","3۔ مالیاتی: قومی خزانے پر کنٹرول؛ وزیرِ خزانہ کا پیش کردہ بجٹ منظور، مسترد یا ترمیم کرنا؛ اس کی اجازت کے بغیر خزانے سے ایک پیسہ نہیں نکل سکتا۔","4۔ عدالتی: اعلیٰ عدالتوں کے ججوں کی تقرری کی توثیق؛ صدر کا مواخذہ۔ 5۔ انتخابی: وزیرِاعظم، اسپیکر و ڈپٹی اسپیکر اور (صوبائی اسمبلیوں کے ساتھ مل کر) صدر کا انتخاب۔","6۔ متفرق: دو تہائی اکثریت سے آئین میں ترمیم؛ قومی پالیسیوں اور بین الاقوامی معاملات پر بحث؛ عوامی شکایات کی نمائندگی۔"]},{"q":[["civ12-ch1-exercise-2",10]],"s":["عاملہ (انتظامیہ) حکومت کا وہ شعبہ ہے جو مقننہ کے بنائے ہوئے قوانین کو عملی شکل دیتا اور ملک کا انتظام چلاتا ہے؛ پاکستان میں یہ صدر، وزیرِاعظم، کابینہ اور سرکاری ملازمین پر مشتمل ہے۔","1۔ انتظامی ذمہ داریاں: قوانین کا نفاذ؛ وزیرِاعظم عاملہ کا سربراہ اور اصل حکمران؛ وزرا کی تقرری؛ اہم عہدوں (چیف الیکشن کمشنر، سفیر، اٹارنی جنرل، آڈیٹر جنرل وغیرہ) پر تقرریاں؛ ہر محکمہ ایک وزیر کے تحت۔","2۔ قانون سازی میں کردار: صدر پارلیمنٹ کا اجلاس طلب و برخاست کرتا، وزیرِاعظم کے مشورے پر قومی اسمبلی تحلیل کرتا اور پیغامات بھیجتا ہے؛ وزرا مسودۂ قانون تیار کرتے ہیں۔","3۔ عدالتی: صدر اعلیٰ عدلیہ اور وفاقی شرعی عدالت کے جج مقرر کرتا اور سزائیں معاف یا کم کر سکتا ہے؛ عدالتی احکامات پر عمل درآمد کروانا عاملہ کی ذمہ داری ہے۔","4۔ فوجی و سفارتی: صدر مسلح افواج کا سربراہ، اعلیٰ فوجی تقرریاں اور سفیروں کا تقرر۔ 5۔ مالیاتی: بجٹ کی تیاری اور خرچ؛ امن و امان کا قیام اور عوامی خدمات کی فراہمی۔"]},{"q":[["civ12-ch1-exercise-2",11]],"s":["پاکستان میں عدلیہ آزاد ہے؛ سپریم کورٹ اس کی چوٹی کی عدالت ہے، ہر صوبے میں ہائی کورٹ، نیز وفاقی شرعی عدالت اور ماتحت عدالتیں ہیں۔","ابتدائی اختیار: وفاق اور صوبوں یا صوبوں کے درمیان تنازعات کا فیصلہ؛ بنیادی حقوق کے نفاذ کے لیے احکامات۔ اپیلیٹ اختیار: ہائی کورٹوں کے فیصلوں کے خلاف اپیلیں سننا۔","مشاورتی اختیار: صدر کسی قانونی یا آئینی مسئلے پر سپریم کورٹ سے رائے لے سکتا ہے۔ آئین کی محافظ: آئین کی کسی مبہم دفعہ کی تشریح کرنا جو آئین کا حصہ بن جاتی ہے؛ آئین سے متصادم قوانین کو کالعدم قرار دینا۔","بنیادی حقوق کا تحفظ: کسی شہری کی درخواست پر بنیادی حقوق کے منافی قانون یا حکم کو کالعدم قرار دینا؛ کسی شخص، ادارے یا دستاویز کو عدالت میں طلب کرنا؛ ہائی کورٹوں کو ہدایات دینا اور مقدمات ایک ہائی کورٹ سے دوسری میں منتقل کرنا۔","ازخود نوٹس (سوموٹو): چیف جسٹس عوامی اہمیت کے معاملات میں خود کارروائی کر سکتا ہے؛ صدر کی منظوری سے عدالتی قواعد بنانا۔ وفاقی شرعی عدالت اسلام کے منافی قوانین کا جائزہ لیتی ہے۔"]},{"q":[["civ12-ch1-exercise-2",13]],"s":["پولیس حکومت کی اہم شاخ ہے جس کی بنیادی ذمہ داری ملک کے اندر امن و امان قائم رکھنا ہے؛ حالات قابو سے باہر ہوں تو حکومت نیم فوجی دستوں یا فوج کو مدد کے لیے بلا سکتی ہے۔","جرائم کی روک تھام اور تفتیش، شہریوں کے جان و مال کا تحفظ، مجرموں کی گرفتاری اور عدالت میں مقدمات کی پیروی۔","ٹریفک پولیس: ڈرائیونگ لائسنس جاری کرنا، سڑکوں پر گشت اور چوراہوں پر ڈیوٹی، ٹریفک کا نظم، حادثات کی روک تھام اور ٹریفک قوانین پر عمل کروانا۔","ضلع کی سطح پر دو شاخیں: تفتیشی شاخ — مقدمات تیار کرنا، عدالت اور پولیس کے ریکارڈ کی دیکھ بھال، فنگر پرنٹس اور سائنسی لیبارٹریوں سے حقائق تک پہنچنا؛ آپریشنل شاخ — گشت، گرفتاریاں اور امن و امان۔","خفیہ پولیس اپنے ایجنٹوں کے ذریعے پیشگی حالات کا اندازہ لگا کر جرائم اور حادثات کی روک تھام میں مدد دیتی ہے۔"]},{"q":[["civ12-ch1-exercise-2",14]],"s":["مسلح افواج پاکستان کا انتہائی اہم ریاستی ادارہ ہیں؛ قانوناً ملکی سرحدوں کی حفاظت اور اندرونی و بیرونی حملوں سے دفاع فوج کی سب سے اہم ذمہ داری ہے۔","آئین کے تحت ہنگامی حالات میں، جب صورتحال سول انتظامیہ کے قابو سے باہر ہو، حکومت فوج کو طلب کر سکتی ہے — قدرتی آفات (زلزلہ، سیلاب)، نسلی و لسانی فسادات، امن و امان کی خرابی اور دہشت گردی کے خلاف۔","فوج تربیتی ادارہ بھی ہے: روایتی معاشرے سے آنے والے افراد کو جدید تعلیم، تربیت اور ہنر دیتی ہے؛ اس کے صنعتی اور تعمیراتی ادارے ملکی ترقی میں حصہ لیتے ہیں۔","اقوامِ متحدہ کی امن فوج میں پاکستانی فوج کا نمایاں کردار رہا ہے۔","البتہ فوج کا ترقیاتی اور سیاسی معاملات میں حد سے زیادہ الجھنا اس کے اصل فرض یعنی دفاع کو متاثر کرتا ہے؛ اس لیے ضروری ہے کہ فوج آئین کے مطابق اپنے پیشہ ورانہ دائرے میں رہے۔"]},{"q":[["civ12-ch1-exercise-2",15]],"s":["عوامی شرکت: جمہوریت کی بنیاد عوام کی شرکت ہے؛ جتنی مؤثر شرکت ہوگی نظام اتنا ہی مستحکم ہوگا۔ ذرائع ابلاغ کی آزادی: شہریوں کی سیاسی تربیت اور شعور کی بیداری۔","جمہوری سیاسی ثقافت: برداشت اور رواداری کا فروغ؛ حزبِ اختلاف کا احترام — اسے ڈرانا، قید کرنا یا کچلنا نہ ہو۔","آزاد عدلیہ اور بلا امتیاز انصاف؛ میرٹ اور اہلیت کا احترام؛ عوام کی فلاح — صحت، تعلیم، روزگار۔","انسانی حقوق کی فراہمی؛ قومی و اجتماعی مفادات کی بالادستی؛ اچھے امیدواروں کا انتخاب (ووٹروں کا کلیدی کردار)۔","سیاسی جماعتوں کا مثبت کردار اور اندرونی جمہوریت؛ آئین کی بالادستی، بروقت اور شفاف انتخابات، احتساب اور اداروں کا اپنی آئینی حدود میں رہنا۔"]}],"activities":[{"q":[["civ12-ch1-exercise-2",17]],"s":["مباحثے کے لیے نکات (حکومت کو مزید جمہوری بنانے کی تجاویز): (1) بروقت، آزاد اور شفاف انتخابات؛ (2) بلدیاتی اداروں کو اختیارات کی منتقلی؛ (3) سیاسی جماعتوں میں اندرونی جمہوریت؛ (4) آزاد عدلیہ اور میڈیا؛ (5) پارلیمنٹ کی بالادستی اور حکومت کا احتساب؛ (6) میرٹ، شفافیت اور عوامی شکایات کا ازالہ؛ (7) شہری تعلیم اور ووٹ کے درست استعمال کا شعور۔","طریقہ: کلاس کو دو گروپوں میں تقسیم کریں؛ ہر گروپ اپنی تجاویز اور دلائل پیش کرے، استاد منصف ہو، آخر میں بہترین تجاویز کا خلاصہ بورڈ پر لکھا جائے۔"]},{"q":[["civ12-ch1-exercise-2",18]],"s":["مضمون نویسی کے مقابلے کا خاکہ — موضوع: \"جمہوریت میں ذرائع ابلاغ اور عدلیہ کی آزادی\"۔","مضمون کے نکات: (1) تمہید — جمہوریت کا مفہوم؛ (2) آزاد میڈیا عوام کو آگاہی دیتا، رائے عامہ ہموار کرتا اور حکومت کا احتساب کرتا ہے؛ (3) آزاد عدلیہ بنیادی حقوق اور آئین کی محافظ ہے اور بلا امتیاز انصاف فراہم کرتی ہے؛ (4) پاکستان میں ان اداروں کی آزادی کو درپیش مسائل اور مثالیں (عدلیہ بحالی تحریک)؛ (5) ذمہ دارانہ آزادی کی ضرورت؛ (6) نتیجہ۔","طریقہ: طلبہ مقررہ وقت میں مضمون لکھیں، اساتذہ معیار (مواد، دلائل، زبان) کے مطابق جانچیں اور بہترین مضامین کو انعام دیا جائے۔"]}]}},"2":{"lang":"ur","items":{"objective":[{"q":[["civ12-ch2-exercise",2]],"s":["انسانیت","دنیا میں بچوں کی خرید و فروخت کا مکروہ کاروبار جاری ہے جو انسانیت کی توہین ہے؛ کنونشن کی دفعہ 35 کے تحت ریاستیں اس کی روک تھام کی پابند ہیں۔"],"a":"انسانیت"},{"q":[["civ12-ch2-exercise",3]],"s":["منشیات","کنونشن کی دفعہ 33 کے مطابق ریاستیں بچوں کو منشیات کے استعمال اور ان کی تجارت سے بچانے کی پابند ہیں۔"],"a":"منشیات"},{"q":[["civ12-ch2-exercise",4]],"s":["ممانعت","قرآن کی انیس آیات میں یتیم لڑکوں اور لڑکیوں سے سخت اور ظالمانہ سلوک کی ممانعت کی گئی ہے اور ان سے نرمی و انصاف کی تاکید کی گئی ہے۔"],"a":"ممانعت"},{"q":[["civ12-ch2-exercise",5]],"s":["برابر (مساوی)","اسلامی شریعت کی نظر میں مرد اور عورت دونوں برابر ہیں؛ روحانی حقوق میں کسی کو کسی پر برتری نہیں۔"],"a":"برابر (مساوی)"},{"q":[["civ12-ch2-exercise",6]],"s":["مرضی","شادی کرنا عورت کا حق ہے اور نکاح میں عورت کی مرضی معلوم کرنا بھی اس کا حق ہے (صحیح بخاری)۔"],"a":"مرضی"},{"q":[["civ12-ch2-exercise",7]],"d":"civ12-ch2-match","s":["درست جوڑ:","مساوی — حقوق۔","عزتِ — نفس۔","حقوق کا — عالمی کنونشن۔","امتیازی — سلوک۔","ذہنی — استعداد۔"]}],"shortQuestions":[{"q":[["civ12-ch2-exercise",9]],"s":["ہر وہ انسان بچہ ہے جو ابتدائی عمر میں ہو، والدین پر انحصار کرتا ہو اور عملی زندگی اور خود انحصاری کے قابل نہ ہو۔","مختلف ممالک نے بچوں کی عمر کی مختلف حدیں مقرر کی ہیں؛ بچوں کے حقوق کے عالمی کنونشن (CRC) کے مطابق بچہ ہر وہ انسان ہے جس کی عمر اٹھارہ سال سے کم ہو۔"]},{"q":[["civ12-ch2-exercise",10]],"s":["دنیا بھر میں بچوں پر زیادتیاں کی جاتی ہیں، ان کے بنیادی حقوق پامال ہوتے ہیں اور انہیں غیر انسانی سلوک کا سامنا ہے؛ لڑکوں اور لڑکیوں سے جبری مشقت کا رواج عام ہو رہا تھا، خصوصاً ترقی پذیر اور پسماندہ ممالک میں۔","یتیم، بے سہارا، غریب اور معذور بچے غیر انسانی رویوں کا شکار تھے؛ بچے معصوم ہیں اور انہیں صحت، تعلیم، تربیت اور نگہداشت کی ضرورت ہے۔ اسی لیے عالمی سطح پر بچوں کے حقوق کا کنونشن منظور کیا گیا جو 2 ستمبر 1990ء سے نافذ ہوا۔"]},{"q":[["civ12-ch2-exercise",11]],"s":["اسلام میں عورتوں کو قرآن و حدیث سے ثابت کئی سیاسی حقوق حاصل ہیں: مومن مرد اور مومن عورتیں ایک دوسرے کے مددگار اور دوست ہیں (سورۃ التوبہ)۔","فتحِ مکہ کے موقع پر نبی کریم ﷺ نے عورتوں سے الگ بیعت لی؛ عورتوں کو رائے دینے، مشورہ دینے اور نیکی کا حکم دینے اور برائی سے روکنے کا حق ہے۔","حضرت عمرؓ نے حضرت شفا بنت عبداللہؓ کو بازار کا نگران مقرر کیا؛ یوں عورت سرکاری ذمہ داریاں بھی انجام دے سکتی ہے۔"]},{"q":[["civ12-ch2-exercise",12]],"s":["خاندان معاشرے کی بنیادی اکائی اور بچوں کی نشوونما کا فطری ماحول ہے؛ کنونشن کی تمہید اور دفعہ 9 میں خاندانی زندگی کی اہمیت پر زور دیا گیا ہے اور بچوں کو ان کی مرضی کے بغیر والدین سے جدا نہیں کیا جا سکتا۔","اسلام بھی خاندانی زندگی کی حوصلہ افزائی کرتا ہے؛ بچوں کا حق ہے کہ انہیں والدین کا پیار، شفقت، اچھی تربیت، تعلیم اور تحفظ ملے۔ خاندان ہی بچے کی شخصیت، اخلاق اور اعتماد کی بنیاد رکھتا ہے۔"]}],"longQuestions":[{"q":[["civ12-ch2-exercise",14]],"s":["بچوں کے حقوق کا عالمی کنونشن (CRC) 1990ء میں نافذ ہوا جبکہ اسلام نے چودہ سو سال پہلے بچوں کو جامع حقوق دیے۔ تقابل:","خاندانی زندگی: کنونشن خاندان کی اہمیت پر زور دیتا ہے؛ اسلام بھی خاندانی زندگی کی حوصلہ افزائی کرتا اور والدین کی محبت و شفقت کو بچے کا حق قرار دیتا ہے۔ عزتِ نفس: کنونشن (دفعات 16، 37) بچوں کی عزت و ساکھ کے تحفظ اور ظالمانہ سزاؤں کی ممانعت کرتا ہے؛ نبی کریم ﷺ نے بچوں کی عزتِ نفس کا خیال رکھنے کی تعلیم دی۔","یتیم اور لاوارث بچے: کنونشن (دفعہ 20) خصوصی تحفظ، رضاعی ماں اور کفالت کا انتظام کرتا ہے؛ قرآن کی انیس آیات میں یتیموں سے ظلم کی ممانعت اور ان کی کفالت پر جنت کی بشارت ہے۔ منشیات: کنونشن بچوں کو منشیات سے بچانے کا پابند کرتا ہے؛ اسلام میں منشیات ہر انسان کے لیے حرام ہیں۔","تعلیم: کنونشن (دفعات 28، 29) مفت اور لازمی ابتدائی تعلیم کا حق دیتا ہے؛ اسلام میں علم حاصل کرنا ہر مسلمان پر فرض ہے۔ والدین کی ذمہ داریاں: کنونشن والدین کی نگہداشت کا حق دیتا ہے؛ حضرت عمرؓ کے مطابق بیٹے کا باپ پر حق ہے کہ وہ اچھی ماں چنے، اچھا نام رکھے اور قرآن سکھائے۔ شناخت: کنونشن نام اور قومیت کا حق دیتا ہے؛ اسلام نے منہ بولے بیٹے کو اصل نسب کے نام سے پکارنے کا حکم دیا۔","خرید و فروخت، جسمانی و اخلاقی تحفظ اور بقا میں بھی دونوں میں ہم آہنگی ہے؛ کنونشن کی کئی باتیں اسلام میں براہِ راست مذکور نہیں مگر اسلام نے ان سے منع بھی نہیں کیا بلکہ بالواسطہ حوصلہ افزائی کی ہے۔ اسلام کے حقوق اللہ کی طرف سے ہیں اور فرائض کے ساتھ مربوط ہیں۔"]},{"q":[["civ12-ch2-exercise",15]],"s":["اسلام ایک مکمل ضابطۂ حیات ہے جس نے عورت کو تفصیلی حقوق دیے: روحانی مساوات — مرد اور عورت کو یکساں روحانی حقوق؛ کسی کو کسی پر برتری نہیں سوائے تقویٰ کے۔","عزت و تحفظ: اسلام سے پہلے لڑکیوں کو زندہ دفن کیا جاتا تھا؛ اسلام نے اسے حرام قرار دیا اور عورت کو بیٹی، بیوی، ماں اور بہن کی حیثیت سے عزت دی؛ وراثت میں حصہ مقرر کیا۔","تعلیم: اسلام میں عورت کے لیے علم حاصل کرنا ضروری ہے؛ حضرت عائشہؓ بڑی عالمہ تھیں۔ معاشی حقوق: عورت جائیداد کی مالک ہو سکتی اور اپنی کمائی اپنے پاس رکھ سکتی ہے؛ بیوی کتنی ہی امیر ہو، اس کا نان نفقہ اور رہائش شوہر کی ذمہ داری ہے۔","نکاح: نکاح عورت کا حق ہے اور اس کی مرضی معلوم کرنا ضروری ہے؛ زبردستی کیا گیا نکاح نبی کریم ﷺ نے رد فرمایا؛ حق مہر اور خلع کا حق بھی دیا گیا۔","سیاسی حقوق: عورتوں سے الگ بیعت لی گئی، انہیں رائے اور مشورے کا حق دیا گیا اور سرکاری ذمہ داریاں بھی سونپی گئیں (حضرت شفاؓ)۔"]}],"activities":[{"q":[["civ12-ch2-exercise",17]],"s":["پوسٹرز، بینرز اور پلے کارڈز کے نعرے: \"ہر بچے کا حق — تعلیم\"، \"بچوں سے مشقت نہیں، قلم دو\"، \"بچوں پر تشدد جرم ہے\"، \"اٹھارہ سال سے کم عمر بچہ ہے\"۔","طریقہ: طلبہ گروپوں میں چارٹ اور بینرز تیار کریں، کنونشن کی اہم دفعات اور اسلامی تعلیمات (یتیموں اور بچوں سے حسنِ سلوک) لکھیں، اور استاد کی نگرانی میں سکول یا محلے میں آگاہی واک کریں۔"]},{"q":[["civ12-ch2-exercise",18]],"s":["کسی عالمِ دین کو کلاس میں مدعو کر کے بچوں اور خواتین کے حقوق پر گفتگو کا اہتمام کیا جائے۔","زیرِ بحث نکات: اسلام میں بچوں کے حقوق (تعلیم، تربیت، نام، کفالت، یتیموں کے حقوق) اور خواتین کے حقوق (تعلیم، وراثت، نکاح میں مرضی، معاشی و سیاسی حقوق)؛ طلبہ سوالات تیار کر کے پوچھیں اور آخر میں نکات کا خلاصہ لکھیں۔"]}]}},"3":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch3-exercise-1",2],["civ12-ch3-exercise-1",3]],"inline":1,"s":["عالمگیریت کی وجہ سے کثیر القومی کارپوریشنیں پوری دنیا میں سرگرم ہو گئی ہیں؛ کوئی سرمایہ کار دنیا میں کہیں بھی سرمایہ کاری اور پیداوار کر سکتا ہے۔"],"c":2},{"q":[["civ12-ch3-exercise-1",4],["civ12-ch3-exercise-1",5]],"inline":1,"s":["عالمی بینک کے اعداد و شمار کے مطابق آئی ایم ایف کے وسائل ترقی پذیر ممالک کی ضروریات سے بہت کم ہیں، اس لیے جی ٹوئنٹی ممالک کو آئی ایم ایف کے وسائل تین گنا بڑھانے کی ضرورت ہے۔"],"c":1},{"q":[["civ12-ch3-exercise-1",6],["civ12-ch3-exercise-1",7]],"inline":1,"s":["2003ء میں یورپی یونین پاکستان کا سب سے بڑا تجارتی شراکت دار رہا اور پاکستان کی ایک تہائی برآمدات خریدیں۔"],"c":2},{"q":[["civ12-ch3-exercise-1",8],["civ12-ch3-exercise-1",9]],"inline":1,"s":["پاکستان عالمی تجارتی تنظیم (WTO) کا رکن ہے۔"],"c":2},{"q":[["civ12-ch3-exercise-1",10],["civ12-ch3-exercise-1",11]],"inline":1,"s":["پاکستانی معاشرہ روایت پسندی، جاگیردارانہ نظام اور رجعت پسندانہ سوچ پر قائم ہے؛ زندگی کے ہر شعبے میں روایت پسندی کی جھلک صاف نظر آتی ہے۔"],"c":0},{"q":[["civ12-ch3-exercise-1",12],["civ12-ch3-exercise-1",13]],"inline":1,"s":["قرضوں کے بوجھ کی وجہ سے بین الاقوامی برادری میں ہمارا حقیقی باوقار مقام نہیں ہے؛ مقروض قوم کو عزت کی نگاہ سے نہیں دیکھا جاتا۔"],"c":2}],"objective":[{"q":[["civ12-ch3-exercise-1",15]],"tf":"tf","s":["غلط۔ سیاست اور معیشت کو ایک دوسرے سے جدا نہیں کیا جا سکتا؛ دونوں ایک دوسرے پر گہرے اور دیرپا اثرات ڈالتے ہیں۔"],"c":1},{"q":[["civ12-ch3-exercise-1",16]],"tf":"tf","s":["صحیح۔ باوقار، آزاد اور خود مختار قوم بننے کے لیے بیرونی قرضوں اور امداد پر انحصار کم کر کے بتدریج ختم کرنا چاہیے اور اپنے وسائل میں رہ کر زندگی گزارنی چاہیے۔"],"c":0},{"q":[["civ12-ch3-exercise-1",17]],"tf":"tf","s":["غلط۔ عالمی بینک انسانی وسائل کی ترقی پر کام کر رہا ہے؛ تعلیم خصوصاً فنی تعلیم، جامعات اور اساتذہ کی تربیت کے اداروں کا قیام اس کی ترجیحات میں شامل ہے۔"],"c":1},{"q":[["civ12-ch3-exercise-1",18]],"tf":"tf","s":["غلط۔ دنیا کے شمال میں امیر ممالک ہیں جبکہ جنوب میں غریب ممالک کی اکثریت ہے۔"],"c":1},{"q":[["civ12-ch3-exercise-1",19]],"tf":"tf","s":["صحیح۔ پاکستان سارک (جنوبی ایشیائی علاقائی تعاون کی تنظیم) کا اہم رکن ہے، نیز ای سی او کا بھی سرگرم رکن ہے۔"],"c":0},{"q":[["civ12-ch3-exercise-1",20]],"tf":"tf","s":["صحیح۔ پاکستان کے قومی بجٹ کا بہت بڑا حصہ فوجی مقاصد پر خرچ ہوتا ہے؛ اس کی بڑی وجہ پاک بھارت کشیدگی اور مسئلۂ کشمیر ہے۔"],"c":0},{"q":[["civ12-ch3-exercise-1",21]],"tf":"tf","s":["غلط۔ پاکستان میں غیر ملکی سرمایہ کاری کی کمی ہے؛ اس کی وجوہات میں حکومتی مراعات کی کمی، بدامنی اور دہشت گردی شامل ہیں۔"],"c":1},{"q":[["civ12-ch3-exercise-1",22]],"tf":"tf","s":["غلط۔ خود انحصاری کے لیے ملکی مصنوعات کو غیر ملکی مصنوعات پر ترجیح دینے کی ضرورت ہے۔"],"c":1}],"shortQuestions":[{"q":[["civ12-ch3-exercise-1",24]],"s":["معاشی عالمگیریت کا مطلب یہ ہے کہ معیشت نے عالمی صورت اختیار کر لی ہے اور معیشت کے لحاظ سے دنیا ایک گاؤں کی مانند ہے۔","اس میں مواصلات کا تیز پھیلاؤ، عالمی منڈیاں، غیر ملکی سرمایہ کاری اور کثیر القومی کارپوریشنوں کا قیام شامل ہے؛ کوئی بھی سرمایہ کار دنیا میں کہیں بھی سرمایہ لگا سکتا اور مال تیار کر کے بیچ سکتا ہے۔"]},{"q":[["civ12-ch3-exercise-1",25]],"s":["اہم برآمدات: سوتی کپڑا، سلے سلائے کپڑے، اون، چاول وغیرہ (پانچ قسم کی اشیا برآمدی آمدنی کا تقریباً 60 فیصد ہیں)؛ بڑا خریدار امریکہ (تقریباً 21 فیصد)، پھر برطانیہ، ہانگ کانگ اور جرمنی۔","اہم درآمدات: مشینری، تیل، کیمیکلز اور نقل و حمل کا سامان — امریکہ، جاپان، ملائیشیا، سعودی عرب اور امارات سے۔"]},{"q":[["civ12-ch3-exercise-1",26]],"s":["عالمی تجارتی اداروں (ڈبلیو ٹی او) کے منفی اثرات: (1) ہم ترقی یافتہ ممالک کی مصنوعات کا مقابلہ نہیں کر سکتے، اس لیے زرعی اور صنعتی ترقی متاثر ہوئی اور بے روزگاری بڑھی۔","(2) غیر ملکی اشیا کے شوق سے دولت بیرونِ ملک منتقل ہوئی اور ادائیگیوں کے توازن میں خسارہ ہوا۔","(3) غربت بڑھی، معیارِ زندگی گرا، حکومت کی آمدنی متاثر ہوئی اور قرضوں کا بوجھ بڑھا۔"]},{"q":[["civ12-ch3-exercise-1",27]],"s":["عالمی تجارتی معاہدے کے منفی اثرات پر قابو پانے کے لیے پاکستان سارک، اقتصادی تعاون تنظیم (ای سی او) اور آزاد علاقائی تجارتی معاہدوں کو ترجیح دے رہا ہے۔","علاقائی تجارت میں ہمسایہ ممالک (بنگلہ دیش، بھارت، سری لنکا، چین) سے کم فاصلے کی وجہ سے نقل و حمل سستی، منڈیاں قریب اور مقابلہ نسبتاً آسان ہوتا ہے؛ چین کے ساتھ خصوصی تجارتی تعلقات بھی بڑھائے جا رہے ہیں۔"]}],"longQuestions":[{"q":[["civ12-ch3-exercise-1",29]],"s":["خود انحصاری پر مبنی معیشت وہ ہے جو کسی غیر ملکی امداد اور سہارے کے بغیر اپنے وسائل پر قائم ہو؛ اس میں درآمدات اور غیر ملکی اشیا کے استعمال کی حوصلہ شکنی اور ملکی مصنوعات کے استعمال کی حوصلہ افزائی کی جاتی ہے۔","اہمیت: خود انحصاری خود داری کی علامت ہے؛ مالیاتی ادارے قرض لینے والے کمزور ممالک کی زندگی کے ہر پہلو پر اثر انداز ہوتے ہیں، اس لیے باوقار اور خود مختار قوم بننے کے لیے آئی ایم ایف اور عالمی بینک پر انحصار کم کرنا ضروری ہے — یعنی \"چادر دیکھ کر پاؤں پھیلانا\"۔","طریقے: آرام طلبی ترک کر کے ہر فرد کا فعال کردار؛ زراعت، صنعت اور توانائی کو ترجیح دے کر ملکی پیداواری صلاحیت بڑھانا؛ تعلیم، سائنس و ٹیکنالوجی اور منصوبہ بندی؛ ملکی مصنوعات کو ترجیح۔","اداروں میں مثبت اور پائیدار اصلاحات — انتظامی، سیاسی، سماجی اور معاشی ڈھانچوں میں تبدیلی؛ کفایت شعاری اور غیر ضروری درآمدات پر پابندی۔","نتیجہ: پیداوار بڑھنے سے بیرونی انحصار خود بخود کم ہو جاتا ہے؛ خود انحصار معیشت ہی آزاد خارجہ پالیسی، قومی وقار اور پائیدار ترقی کی ضامن ہے۔"]},{"q":[["civ12-ch3-exercise-1",30]],"s":["مثبت اثرات: مواصلات میں آسانی اور تیزی — دنیا میں کہیں بھی لمحوں میں رابطہ اور معلومات تک رسائی؛ زندگی کے تمام شعبوں میں ٹیکنالوجی کی تیز رفتار ترقی؛ غیر ملکی سرمایہ کاری، تجارت اور روزگار کے نئے مواقع؛ جدید علم اور مہارتوں تک رسائی۔","منفی اثرات: ثقافتی یلغار — عالمی ادارے اور کثیر القومی کمپنیاں ثقافتی اثرات بڑھاتی ہیں جس سے مقامی اقدار متاثر ہوتی ہیں۔","پاکستان ترقی پذیر ملک ہے؛ کھلی عالمی منڈی میں پاکستانی مصنوعات ترقی یافتہ ممالک کے مقابلے میں کمزور ہیں، جس سے مقامی صنعت کو دھچکا لگتا اور بے روزگاری بڑھتی ہے۔","درآمدات میں اضافہ، تجارتی خسارہ، قرضوں پر انحصار اور معیشت پر عالمی اداروں کا کنٹرول بڑھتا ہے۔","لہٰذا پاکستان کو عالمگیریت کے فوائد سے استفادہ کرنے کے لیے اپنی صنعت کا معیار، تعلیم اور ٹیکنالوجی بہتر بنانی ہوگی۔"]},{"q":[["civ12-ch3-exercise-1",31]],"s":["خود انحصاری کا مطلب ہے کہ فرد یا ملک دوسروں کے بجائے خود پر انحصار کرے؛ یہ عزتِ نفس کی ایک صورت ہے۔ اس کے لوازمات:","(1) عالمی مالیاتی اداروں پر انحصار میں بتدریج کمی اور ملکی وسائل کے اندر رہ کر زندگی گزارنا؛ (2) آرام طلبی کا خاتمہ، محنت اور ہر فرد کا فعال کردار۔","(3) ملکی پیداواری صلاحیت میں اضافہ — زراعت، صنعت اور توانائی کو ترجیح؛ موجودہ وسائل کا استعمال؛ تعلیم، سائنس اور ٹیکنالوجی کا فروغ اور مناسب منصوبہ بندی۔","(4) ملکی مصنوعات کو غیر ملکی اشیا پر ترجیح؛ غیر ضروری درآمدات کی حوصلہ شکنی؛ کفایت شعاری۔","(5) تمام اداروں میں مثبت اور پائیدار اصلاحات، ٹیکس چوری کا خاتمہ، بدعنوانی پر قابو اور سیاسی استحکام۔"]},{"q":[["civ12-ch3-exercise-1",33]],"s":["(1) عالمی بینک (بین الاقوامی بینک برائے تعمیرِ نو و ترقی): 27 دسمبر 1945ء کو بریٹن ووڈز کانفرنس میں 29 ممالک کے معاہدے سے قائم ہوا۔ مقاصد: رکن ممالک کو پیداواری سرمایہ کاری کی سہولت، تعمیرِ نو و ترقی، نجی سرمایہ کاری اور متوازن عالمی تجارت کا فروغ۔ کام: ترقیاتی منصوبوں کے لیے قرضے (پاکستان میں بجلی کی لائنیں، 1997ء میں نکاسیٔ آب کے لیے 285 ملین ڈالر)، صنعتی قرضے دینے والے اداروں کو مضبوط کرنا (PICIC)، انسانی وسائل اور تعلیم کی ترقی، نجکاری اور مالی اصلاحات، اچھی حکمرانی، زراعت اور قدرتی وسائل کا انتظام۔","(2) آئی ایم ایف (بین الاقوامی مالیاتی فنڈ): دوسری جنگ عظیم کے بعد بریٹن ووڈز کانفرنس میں قائم ہوا۔ مقاصد: بین الاقوامی مالیاتی تعاون، عالمی تجارت کی سہولت، شرحِ مبادلہ میں استحکام، ادائیگیوں میں کثیر الطرفہ تعاون، رکن ممالک کو فنڈز اور مساوی معاشی مواقع۔ کام: جنگ زدہ یورپی معیشتوں کو بچایا، شرحِ مبادلہ کا تعین اور مہنگائی پر قابو، خسارے والے ممالک کو مالی وسائل، 1990ء کی دہائی میں وسطی ایشیائی ریاستوں کی مدد۔","(3) ایشیائی ترقیاتی بینک: 19 دسمبر 1966ء کو قائم ہوا، صدر دفتر منیلا (فلپائن)۔ مقاصد: غربت کا خاتمہ، انسانی وسائل کی ترقی، معاشی ترقی، خواتین کی حیثیت کی بہتری اور ماحول کا تحفظ۔ کام: زراعت، توانائی، صنعت، مالیات اور مواصلات کے ترقیاتی منصوبوں کے لیے آسان قرضے، فنی امداد اور منصوبوں کی تیاری میں تعاون۔"]},{"q":[["civ12-ch3-exercise-1",34]],"s":["عالمی مالیاتی ادارے امداد دینے اور لینے والوں دونوں پر سیاسی اثرات ڈالتے ہیں؛ امداد لینے والے رقوم حاصل کرتے ہیں جبکہ دینے والے سیاسی اور سفارتی مقاصد حاصل کرتے ہیں۔","(1) عالمی بینک، آئی ایم ایف اور گیٹ امریکہ کی خاص دلچسپی سے قائم ہوئے؛ بظاہر مقصد یورپ کی معیشت کو سہارا دینا تھا مگر سیاسی طور پر امریکی اثر و رسوخ بڑھانا تھا۔ (2) قرض لینے والے ممالک کے فیصلوں پر اثر انداز ہونا؛ کمزور ممالک کو ہدایات ماننا پڑتی ہیں۔","(3) امداد میں فوجی اور دفاعی مقاصد بھی شامل ہوتے ہیں۔ (4) تجارتی اور کاروباری مواقع اور سفارتی مفادات کا حصول۔ (5) نجکاری، سیاسی استحکام اور جمہوریت کو مضبوط کرنے کی خواہش۔","(6) عالمی سیاست میں اپنے اتحادی بڑھانا۔ (7) بڑے ممالک کا کمزوروں کا استحصال تاکہ وہ آواز نہ اٹھائیں۔ (8) مقروض ریاستیں ناجائز شرائط ماننے پر مجبور ہو کر اپنا عالمی وقار کھو دیتی ہیں۔","(9) بعض حکمران جماعتیں انتخابی وعدے پورے کرنے اور اپنا سیاسی مستقبل محفوظ بنانے کے لیے قرضے لیتی ہیں۔"]},{"q":[["civ12-ch3-exercise-1",35]],"s":["(1) ترقی یافتہ (شمال) اور ترقی پذیر (جنوب) ممالک کی باہمی مشاورت سے مساوات، انصاف اور برابری پر مبنی نیا عالمی معاشی نظام۔ (2) عالمی تجارت اور مالیاتی نظام کے لیے نئے جامع اصول؛ کمزور ممالک کی برآمدات کی حوصلہ افزائی۔","(3) تیسری دنیا کے لیے محصولات میں کمی اور عالمی خوراک پروگرام۔ (4) سائنس و ٹیکنالوجی کی آسان منتقلی۔ (5) ہر ملک کو اپنا معاشی نظام اپنانے کی آزادی؛ بڑی طاقتوں کی مداخلت اور دباؤ کا خاتمہ۔","(6) سیاست سے بالاتر ہو کر انسانی فلاح کے لیے فنی و مالی تعاون۔ (7) اداروں کے فیصلوں میں قرض لینے والے ممالک کی مؤثر شمولیت۔ (8) قرض کی واپسی کی صلاحیت کے مطابق نرم شرائط۔","(9) تیسری دنیا میں معاشی تعاون کے جذبات کا احترام۔ (10) کثیر القومی کارپوریشنوں کو تیسری دنیا کی حقیقی ترقی کا مددگار بنانا۔ (11) کمزور ممالک کا اپنے قدرتی وسائل پر اختیار۔ (12) خام مال کی قوتِ خرید برقرار رکھنا اور ترقی یافتہ منڈیوں تک رسائی۔","(13) آئی ایم ایف کے ووٹنگ نظام میں تبدیلی — چھوٹے اراکین اور ابھرتی معیشتوں (چین، برازیل) کو زیادہ حقِ رائے؛ پیداواری سرمایہ کاری پر توجہ، امریکی اثر کا خاتمہ اور روایتی بیوروکریسی کی رکاوٹیں دور کرنا۔"]},{"q":[["civ12-ch3-exercise-1",36]],"s":["پاکستان عالمی تجارتی تنظیم (WTO) کا رکن ہے؛ اس کے اثرات: سرمایہ کاری کی حد بہت کم ہو گئی؛ بے روزگاری اور غربت بڑھی اور عوام کا معیارِ زندگی مزید خراب ہوا؛ سماجی برائیاں بالواسطہ طور پر بڑھیں۔","حکومت کی آمدنی اور اخراجات پر منفی اثر؛ سرکاری اور نجی شعبوں کی حوصلہ شکنی اور قومی ترقی میں ان کی شراکت کم ہوئی۔","زرعی اور صنعتی ترقی متاثر ہوئی کیونکہ ہم بین الاقوامی منڈی میں ترقی یافتہ ممالک کی مصنوعات کا مقابلہ نہیں کر سکتے؛ غیر ملکی اشیا میں دلچسپی سے دولت بیرونِ ملک منتقل ہوئی۔","ادائیگیوں کے توازن میں خسارہ؛ گرتے مالیاتی نظام کو سہارا دینے کے لیے قرضوں کا بوجھ بڑھا؛ بنیادی ڈھانچہ متاثر ہوا۔","سیاسی اثرات: معاشی ابتری سے سیاسی عدم استحکام پیدا ہوا؛ ان اثرات پر قابو پانے کے لیے پاکستان سارک، ای سی او اور علاقائی آزاد تجارتی معاہدوں کو ترجیح دے رہا ہے۔"]},{"q":[["civ12-ch3-exercise-1",37]],"s":["بے روزگاری: تعلیم یافتہ نوجوان بے روزگاری کی وجہ سے سماجی برائیوں کا سبب بن رہے ہیں؛ غیر تربیت یافتہ انسانی وسائل۔","دفاعی اخراجات: قومی بجٹ کا بہت بڑا حصہ فوجی مقاصد پر خرچ ہوتا ہے، جس کی بنیادی وجہ پاک بھارت کشیدگی اور مسئلۂ کشمیر ہے؛ دونوں ملکوں کے عوام غریب ہیں مگر وسائل اسلحے پر صرف ہوتے ہیں۔","روایت پسندی اور جاگیردارانہ نظام: معاشرہ رجعت پسندانہ سوچ پر قائم ہے، جدید طریقوں کی مزاحمت۔ غیر ملکی سرمایہ کاری کی کمی: حکومتی مراعات کی کمی، دہشت گردی اور امن و امان کی خراب صورتحال۔","تعلیم کی کمی: شرحِ خواندگی کم اور فنی و سائنسی تعلیم کا رجحان کمزور۔ قرضوں کا بوجھ اور سود کی ادائیگی۔","بدعنوانی اپنے عروج پر ہے جو بہت سی برائیوں کی جڑ اور معاشی استحکام کی راہ میں بڑی رکاوٹ ہے؛ نیز سیاسی عدم استحکام اور ٹیکس چوری۔"]},{"q":[["civ12-ch3-exercise-1",38]],"s":["قرضوں سے نجات اور معاشی ترقی کے اقدامات: درآمدات کی حوصلہ شکنی؛ خود انحصاری اور کفایت شعاری کی راہ؛ غیر ضروری اشیا کی درآمد پر مکمل پابندی؛ عوام میں سادگی کا شعور۔","صنعت کو فروغ دے کر کم لاگت میں معیاری مال تیار کرنا اور برآمدات بڑھانا تاکہ زرِمبادلہ آئے؛ ٹیکس چوری کو آہنی ہاتھوں سے روکنا تاکہ حکومتی آمدنی بڑھے۔","تعلیم، خصوصاً فنی و سائنسی تعلیم کا فروغ؛ بے روزگاری کے خاتمے کے لیے خود روزگار سکیمیں اور ہنر سکھانا؛ بدعنوانی کا خاتمہ اور سرمایہ کاری کے لیے پرامن ماحول۔","قرضوں کے اثرات: قرضوں میں جکڑا ملک یا فرد کبھی خود دار نہیں کہلا سکتا؛ عالمی برادری میں ہمارا باوقار مقام نہیں رہتا؛ پالیسیاں قرض دینے والوں کی شرائط کے تابع ہو جاتی ہیں۔","شہریوں پر اثرات: سود اور قرض کی ادائیگی میں بجٹ کا بڑا حصہ جانے سے تعلیم، صحت اور ترقی کے لیے رقم کم بچتی ہے؛ ٹیکس اور مہنگائی بڑھتی ہے؛ قرضوں کا عیاشی اور فضول خرچی پر ضیاع قومی وقار کو مجروح کرتا ہے۔"]},{"q":[["civ12-ch3-exercise-1",39]],"s":["براہِ راست غیر ملکی امداد: وہ فوجی یا معاشی مدد جو ایک ملک یا عالمی ادارہ کسی دوسرے ملک کو بحران کی حالت میں دیتا ہے؛ یہ نقدی، اشیا، خدمات یا فنی مہارت کی صورت میں، دو طرفہ یا کثیر الملکی ہو سکتی ہے؛ جاپان، برطانیہ اور امریکہ بڑے امداد دینے والے ممالک ہیں۔","معاشی عالمگیریت: معیشت کا عالمی صورت اختیار کرنا، دنیا کا معاشی لحاظ سے ایک گاؤں بن جانا؛ مواصلات کا تیز پھیلاؤ، عالمی منڈیاں، غیر ملکی سرمایہ کاری اور کثیر القومی کارپوریشنیں اس کے اجزا ہیں۔","پائیدار ترقی: وہ ترقی جو طویل عرصے تک مفید طریقے سے قائم رہے (روزانہ امداد کے بجائے روزگار کا ذریعہ دینا)؛ ماہرینِ ماحولیات کے مطابق ایسی معاشی ترقی جو ماحول کو آلودہ کیے بغیر برقرار رہے اور آنے والی نسلوں کے وسائل محفوظ رکھے۔"]}],"activities":[{"q":[["civ12-ch3-exercise-2",1]],"s":["خود انحصاری کی اہمیت پر مضمون نویسی کا مقابلہ: نکات — خود انحصاری کا مفہوم؛ قرضوں کے نقصانات؛ ملکی مصنوعات، محنت اور کفایت شعاری کی اہمیت؛ تعلیم و ٹیکنالوجی؛ قومی وقار۔ بہترین مضامین کو انعام اور سکول میگزین میں اشاعت۔"]},{"q":[["civ12-ch3-exercise-2",2]],"s":["اس باب سے کوئز: مثلاً عالمی بینک کب قائم ہوا؟ (27 دسمبر 1945ء)؛ ایشیائی ترقیاتی بینک کا صدر دفتر کہاں ہے؟ (منیلا)؛ پاکستان کس عالمی تجارتی تنظیم کا رکن ہے؟ (WTO)؛ 2003ء میں پاکستان کا سب سے بڑا تجارتی شراکت دار؟ (یورپی یونین)۔ کلاس کو ٹیموں میں تقسیم کر کے سوال و جواب کا مقابلہ کرایا جائے۔"]},{"q":[["civ12-ch3-exercise-2",3]],"s":["ماہرِ معاشیات کو مدعو کر کے \"پاکستان کی معیشت پر غیر ملکیوں کے اثرات\" پر مباحثہ: ایک گروپ مثبت پہلو (سرمایہ کاری، ٹیکنالوجی، روزگار) اور دوسرا منفی پہلو (قرضے، شرائط، مقامی صنعت کو نقصان، ثقافتی اثرات) پیش کرے؛ ماہر آخر میں تبصرہ اور نتائج بیان کرے۔"]}]}},"4":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch4-exercise-2",1],["civ12-ch4-exercise-2",2]],"inline":1,"s":["1917ء میں فلسطین کا علاقہ ترکی (سلطنتِ عثمانیہ) سے نکل کر برطانیہ کے قبضے میں چلا گیا۔"],"c":3},{"q":[["civ12-ch4-exercise-2",3],["civ12-ch4-exercise-2",4]],"inline":1,"s":["گیارہ ستمبر 2001ء کو نیویارک کے ورلڈ ٹریڈ سینٹر اور امریکہ کے پینٹاگون پر فضائی حملے ہوئے۔"],"c":3},{"q":[["civ12-ch4-exercise-2",5],["civ12-ch4-exercise-2",6]],"inline":1,"s":["اکتوبر 2006ء میں شمالی کوریا نے زیرِ زمین ایٹمی دھماکہ کیا۔"],"c":2},{"q":[["civ12-ch4-exercise-2",7],["civ12-ch4-exercise-2",8]],"inline":1,"s":["دونوں عالمی جنگوں کی وجوہات میں ممالک کے درمیان اسلحے (ہتھیاروں) کی دوڑ بھی شامل ہے۔"],"c":3},{"q":[["civ12-ch4-exercise-2",9],["civ12-ch4-exercise-2",10]],"inline":1,"s":["روس کے وزیرِاعظم کوسیجن کی کوششوں سے 1966ء میں تاشقند میں پاکستان اور بھارت کے درمیان امن معاہدہ ہوا۔"],"c":0},{"q":[["civ12-ch4-exercise-2",11],["civ12-ch4-exercise-2",12]],"inline":1,"s":["ثالث جج کی مانند ہوتا ہے، اس لیے اس کا انصاف پسند، غیر جانبدار اور دیانت دار ہونا بے حد ضروری ہے۔"],"c":0}],"objective":[{"q":[["civ12-ch4-exercise-1",2]],"s":["قیام","14 مئی 1948ء کو اسرائیلی ریاست کے قیام کا اعلان کیا گیا۔"],"a":"قیام"},{"q":[["civ12-ch4-exercise-1",3]],"s":["اتحادیوں","امریکہ اور اس کے اتحادیوں کو جیو اور جینے دو کی پالیسی اپنانی چاہیے۔"],"a":"اتحادیوں"},{"q":[["civ12-ch4-exercise-1",4]],"s":["خانہ جنگی","سری لنکا طویل عرصے تک اندرونی خانہ جنگی کا شکار رہا جہاں تامل ٹائیگرز نامی تنظیم نے زندگی اجیرن کر رکھی تھی۔"],"a":"خانہ جنگی"},{"q":[["civ12-ch4-exercise-1",5]],"s":["ہیگ","عالمی عدالتِ انصاف کا صدر دفتر نیدرلینڈز (ہالینڈ) کے شہر ہیگ میں ہے۔"],"a":"ہیگ"},{"q":[["civ12-ch4-exercise-1",6]],"s":["مسائل اور تنازعات حل کرنے","ثالث بننے کے لیے انسان میں مسائل اور تنازعات حل کرنے کا جذبہ ہونا چاہیے۔"],"a":"مسائل اور تنازعات حل کرنے"},{"q":[["civ12-ch4-exercise-2",14]],"tf":"tf","s":["غلط۔ امریکہ کے ورلڈ ٹریڈ سینٹر اور پینٹاگون پر حملے گیارہ ستمبر 2001ء کو ہوئے، 2011ء میں نہیں۔"],"c":1},{"q":[["civ12-ch4-exercise-2",15]],"tf":"tf","s":["صحیح۔ امریکہ نے مارچ 2003ء میں عراق پر حملہ کیا اور چند دنوں میں اس پر قبضہ کر لیا۔"],"c":0},{"q":[["civ12-ch4-exercise-2",16]],"tf":"tf","s":["صحیح۔ 1965ء کی پاک بھارت جنگ کے بعد سوویت یونین کی ثالثی سے تاشقند معاہدہ ہوا۔"],"c":0},{"q":[["civ12-ch4-exercise-2",17]],"tf":"tf","s":["غلط۔ تنازعات کے حل کے لیے ثالثی ایک مؤثر طریقہ ہے؛ اقوامِ متحدہ اور عالمی شخصیات کی ثالثی سے کئی تنازعات حل ہوئے۔"],"c":1},{"q":[["civ12-ch4-exercise-2",18]],"tf":"tf","s":["غلط۔ اس وقت دنیا کا سب سے خطرناک خطہ فلسطین کی سرزمین ہے، اردن نہیں۔"],"c":1},{"q":[["civ12-ch4-exercise-2",19]],"tf":"tf","s":["غلط۔ لائن آف کنٹرول آزاد کشمیر اور مقبوضہ کشمیر یعنی پاکستان اور بھارت کے درمیان عارضی سرحد ہے، چین کے ساتھ نہیں۔"],"c":1},{"q":[["civ12-ch4-exercise-2",20]],"tf":"tf","s":["صحیح۔ گفت و شنید (مذاکرات) کا مقصد تنازعات کا منصفانہ فیصلہ کرنا ہے۔"],"c":0},{"q":[["civ12-ch4-exercise-2",21]],"tf":"tf","s":["صحیح۔ شمالی کوریا کے پاس ایٹمی ہتھیار ہیں؛ اس نے اکتوبر 2006ء میں ایٹمی دھماکہ کیا۔"],"c":0},{"q":[["civ12-ch4-exercise-2",22]],"d":"civ12-ch4-match","s":["درست جوڑ:","انقلابِ — ایران۔","القاعدہ — طالبان۔","مشرقِ — وسطیٰ۔","شورش — زدہ۔","مغربی — کنارہ۔","شمالی — کوریا۔","سرد — جنگ۔"]}],"shortQuestions":[{"q":[["civ12-ch4-exercise-2",24]],"s":["اسرائیلی ریاست 14 مئی 1948ء کو فلسطین (مشرقِ وسطیٰ) کی سرزمین پر وجود میں آئی۔","1947ء میں اقوامِ متحدہ نے اس علاقے کو فلسطین اور اسرائیل کی دو ریاستوں میں تقسیم کرنے کا فیصلہ کیا تھا جسے عربوں نے مسترد کیا؛ اسرائیل کے قیام کے وقت یہاں 35 فیصد یہودی اور 65 فیصد فلسطینی آباد تھے۔"]},{"q":[["civ12-ch4-exercise-2",25]],"s":["1947–48ء میں کشمیر میں پاک بھارت جنگ روکنے کے لیے اقوامِ متحدہ نے جنگ بندی کا حکم دیا اور آزاد کشمیر اور مقبوضہ کشمیر کے درمیان ایک عارضی لکیر قائم کی جسے لائن آف کنٹرول (LOC) کہتے ہیں۔","اس کی نگرانی کے لیے اقوامِ متحدہ کا فوجی مبصر گروپ بنایا گیا؛ ساتھ یہ بھی تسلیم کیا گیا کہ کشمیریوں کو اپنے سیاسی مستقبل کا فیصلہ کرنے کا حقِ خود ارادیت حاصل ہے۔"]},{"q":[["civ12-ch4-exercise-2",26]],"s":["اوسلو معاہدہ 1993ء میں ناروے کے دارالحکومت اوسلو میں امریکی ثالثی سے شروع ہونے والے مذاکرات کے نتیجے میں فلسطینی نمائندوں (تنظیمِ آزادیٔ فلسطین) اور اسرائیل کے درمیان ہوا۔","اہم نکات: (1) فلسطینی قیادت (یاسر عرفات) نے اسرائیل کو تسلیم کیا؛ (2) اسرائیل نے فلسطینی اکثریتی علاقوں میں مرحلہ وار اقتدار منتقل کرنے پر آمادگی ظاہر کی؛ (3) غزہ کی پٹی اور دریائے اردن کے مغربی کنارے کے کچھ علاقوں میں فلسطینی نیشنل اتھارٹی کا قیام اور خود مختاری (1994–95ء کے معاہدوں کے بعد)۔"]},{"q":[["civ12-ch4-exercise-2",27]],"s":["ثالث جج کی مانند ہوتا ہے، اس لیے غیر جانبدار، مخلص اور دیانت دار ہو؛ فریقین کی نفسیات سمجھنے کی صلاحیت رکھتا ہو۔","تجربہ کار، ٹھنڈے مزاج کا اور صابر ہو؛ ماحول پر نظر رکھے اور معتدل، پرسکون، محفوظ و خوشگوار ماحول یقینی بنائے۔","باکردار ہو کہ دونوں فریق مطمئن ہوں؛ متنازعہ امور کا ماہر ہو تاکہ مسئلے کی جڑ تک پہنچ سکے؛ انصاف پسند اور تعلیم یافتہ ہو۔"]}],"longQuestions":[{"q":[["civ12-ch4-exercise-2",29]],"s":["(1) فلسطین: 1917ء میں فلسطین ترکی سے برطانیہ کے قبضے میں گیا؛ صیہونی تحریک نے یہودیوں کو یہاں بسایا؛ 1947ء میں اقوامِ متحدہ کا تقسیمی فیصلہ؛ 14 مئی 1948ء کو اسرائیل کا قیام؛ 1948–49ء اور 1967ء کی جنگوں میں اسرائیل نے مغربی کنارہ، غزہ اور مشرقی یروشلم پر قبضہ کیا اور لاکھوں فلسطینی بے گھر ہوئے۔","(2) افغانستان: 11 ستمبر 2001ء کے حملوں کے بعد امریکہ اور اتحادیوں نے افغانستان پر حملہ کر کے طالبان حکومت ختم کی، مگر وہاں امن قائم نہ ہو سکا۔ (3) کشمیر: مہاراجہ نے مسلم اکثریت کے باوجود بھارت سے الحاق کیا؛ جنگ کے بعد اقوامِ متحدہ نے استصوابِ رائے کی سفارش کی جس پر بھارت نے عمل نہیں کیا؛ کشمیری حریت کانفرنس آزادی کی جدوجہد کر رہی ہے۔","(4) عراق: امریکہ نے وسیع تباہی کے ہتھیاروں کا الزام لگا کر مارچ 2003ء میں عراق پر حملہ کیا اور صدام حسین کی حکومت ختم کی۔ (5) ایران: ایران کے ایٹمی پروگرام پر امریکہ اور مغرب سے تنازع؛ ایران پرامن استعمال کا دعویٰ کرتا ہے۔","(6) شمالی کوریا: این پی ٹی سے نکل کر ایٹمی پروگرام؛ اکتوبر 2006ء میں ایٹمی دھماکہ۔ (7) پاک بھارت معاملات: کشمیر، دریاؤں کے پانی کی تقسیم (بگلیہار ڈیم، وولر بیراج وغیرہ)، 1965ء اور 1971ء کی جنگیں؛ مذاکرات سے حل شدہ مسائل (تاشقند و شملہ معاہدے)۔","خلاصہ: پچھلی نصف صدی کے بیشتر تنازعات آزادی، علاقے، ایٹمی پروگرام اور بڑی طاقتوں کے مفادات سے جڑے ہیں؛ تاریخ بتاتی ہے کہ جانی و مالی نقصان کے بعد آخرکار قوموں کو مذاکرات کی راہ اپنانا پڑی۔"]},{"q":[["civ12-ch4-exercise-2",30]],"s":["(1) آزادی کا مسئلہ: زیادہ تر عالمی تنازعات آزادی کی تحریکوں کی وجہ سے ہیں؛ آزادی پسندوں کو کچلنے اور انسانی حقوق کی پامالی سے مسائل سنگین ہوتے ہیں (کشمیر، فلسطین)۔","(2) حقِ خود ارادیت سے انکار: معاہدۂ ورسائی اور اقوامِ متحدہ کے منشور میں قوموں کو اپنے سیاسی مستقبل کا فیصلہ کرنے کا حق دیا گیا، مگر اس پر عمل نہیں ہوتا۔","(3) علاقے کی ملکیت: بیشتر تنازعات زمینی ہیں — پاک بھارت جنگیں اور فلسطینیوں و اسرائیل کا بنیادی مسئلہ بھی زمین کا ہے۔","(4) اندرونی خانہ جنگی اور بغاوتیں (سری لنکا میں تامل ٹائیگرز)؛ محرومی، ناانصافی اور جانبداری۔","(5) بڑی طاقتوں (امریکہ، برطانیہ، جرمنی، فرانس، روس) کے مفادات اور مداخلت، اسلحے کی دوڑ، ایٹمی پروگرام، وسائل (تیل، پانی) پر کنٹرول اور نظریاتی اختلافات۔"]},{"q":[["civ12-ch4-exercise-2",31]],"s":["(1) خلوص اور سنجیدگی: جب ممالک سچائی اور دیانت داری سے مسائل حل کرنے کا عزم کریں تو ہر مسئلہ حل ہو سکتا ہے؛ کشمیر اور فلسطین کے مذاکرات سنجیدگی کی کمی سے ناکام ہوئے۔","(2) گفت و شنید (مذاکرات): فریقین کا براہِ راست بات چیت سے منصفانہ حل تلاش کرنا — مثلاً تاشقند و شملہ معاہدے، امریکہ شمالی کوریا معاہدہ (1994ء)، اوسلو معاہدہ۔","(3) مصالحت (سچائی اور مفاہمت): مخالف گروہوں کی ناراضی ختم کر کے دوستانہ ماحول قائم کرنا — جنوبی افریقہ میں نسلی امتیاز کے خاتمے کے بعد سچائی اور مفاہمت کمیشن نے حقائق سامنے لا کر متاثرین کی دادرسی اور قومی مفاہمت کی۔","(4) ثالثی: اقوامِ متحدہ، عالمی و علاقائی ادارے (او آئی سی، عرب لیگ، سارک، یورپی یونین) اور غیر جانبدار ممالک کی ثالثی — جیسے کشمیر میں جنگ بندی اور لائن آف کنٹرول۔","(5) عالمی عدالتِ انصاف سے رجوع، اقوامِ متحدہ کو بااختیار بنانا تاکہ اس کے فیصلے منوائے جا سکیں، اور عالمی راہنماؤں کا سچائی اور دیانت سے آگے بڑھنا۔"]},{"q":[["civ12-ch4-exercise-2",32]],"s":["اقوامِ متحدہ کا کردار: یہ عالمی تنازعات حل کرنے کا اہم ادارہ ہے؛ عرب اسرائیل مسئلے میں ثالثی کی؛ 1947–48ء میں کشمیر میں جنگ بندی کرائی، لائن آف کنٹرول قائم کی، مبصر گروپ بنایا اور کشمیریوں کا حقِ خود ارادیت تسلیم کیا۔ ضرورت ہے کہ اسے بااختیار بنایا جائے تاکہ اس کے فیصلوں پر عمل ہو۔","عالمی عدالتِ انصاف: اقوامِ متحدہ کا کلیدی حصہ ہے جو 1945ء میں اس کے منشور کی روشنی میں قائم ہوئی؛ صدر دفتر ہیگ (نیدرلینڈز) میں ہے۔","کام: (1) رکن ممالک کے درمیان قانونی تنازعات کا فیصلہ؛ (2) اقوامِ متحدہ اور اس کے اداروں کو بین الاقوامی قانون سے متعلق سوالات پر قانونی رائے دینا۔","تمام رکن ممالک اس سے رجوع کر سکتے ہیں؛ غیر رکن ملک بھی شرائط مان کر اور اخراجات میں حصہ ڈال کر فریق بن سکتا ہے۔","مقدمہ دو طریقوں سے آتا ہے: فریقین باہمی رضامندی سے مسئلہ پیش کریں، یا ایک فریق یکطرفہ درخواست دے۔"]},{"q":[["civ12-ch4-exercise-2",33]],"s":["عالمی شہرت یافتہ شخصیات ثالث اور مذاکرات کار کے طور پر نمایاں کردار ادا کر سکتی ہیں۔","اقوامِ متحدہ کا سیکرٹری جنرل: اپنے عہدے کی وجہ سے عالمی سطح پر قابلِ قبول؛ مثلاً بان کی مون نے ترکی سے قبرص اور آرمینیا کے مسائل پرامن طریقے سے حل کرنے کی درخواست کی۔","ہنری کسنجر: اکتوبر 1970ء میں پاکستان آئے؛ یحییٰ خان نے ان کے چین جانے کی راہ ہموار کی، جس کے نتیجے میں صدر نکسن نے چین کا دورہ کیا، امریکہ چین تعلقات قائم ہوئے اور چین اقوامِ متحدہ کا رکن بنا۔","کوسیجن: روسی وزیرِاعظم نے 4 جنوری 1966ء کو تاشقند میں لال بہادر شاستری اور ایوب خان کے درمیان مذاکرات کرا کے تاشقند معاہدہ کرایا۔","امریکی صدور (کلنٹن، بش، اوباما) نے فلسطین اسرائیل مذاکرات کرائے (اوسلو معاہدہ 1993ء)۔ ان مثالوں سے ثابت ہوتا ہے کہ عالمی شہرت یافتہ قیادت ذاتی کردار سے تنازعات کے حل میں مؤثر کردار ادا کر سکتی ہے۔"]}],"activities":[{"q":[["civ12-ch4-exercise-3",1]],"s":["مسئلۂ کشمیر پر تقریری مقابلہ — تقریر کے نکات: تاریخی پسِ منظر (3 جون منصوبہ، مہاراجہ کا الحاق، 1948ء کی جنگ)؛ اقوامِ متحدہ کی استصوابِ رائے کی قراردادیں؛ کشمیریوں کی جدوجہد اور انسانی حقوق کی پامالی؛ خطے کے امن کے لیے اہمیت؛ حل — حقِ خود ارادیت اور بامعنی مذاکرات۔ ججز مواد، دلائل اور اندازِ بیان پر نمبر دیں۔"]},{"q":[["civ12-ch4-exercise-3",2]],"s":["تنازعات کے پرامن حل کے اقدامات: مذاکرات، ثالثی، مصالحت، جرگہ، عدالت سے رجوع، برداشت اور معافی۔","علاقے کے کسی مشہور ثالث یا امن جرگے کے رکن کو مدعو کر کے ان سے پوچھا جائے کہ وہ تنازعات کیسے حل کرتے ہیں، کن خوبیوں کی ضرورت ہوتی ہے اور کامیاب مثالیں کیا ہیں؛ طلبہ نکات لکھ کر رپورٹ تیار کریں۔"]},{"q":[["civ12-ch4-exercise-3",3]],"s":["فرضی فریق بنا کر کلاس میں مظاہرہ: مثلاً دو گروپ پانی یا زمین کے تنازعے کے فریق بنیں اور ایک طالب علم ثالث۔","مراحل: (1) دونوں فریق اپنا مؤقف بیان کریں؛ (2) ثالث غیر جانبداری سے سنے اور مشترکہ مفادات تلاش کرے؛ (3) تجاویز پیش کرے؛ (4) فریقین رعایتیں دے کر سمجھوتے پر پہنچیں؛ (5) معاہدہ لکھ کر دستخط کیے جائیں۔ آخر میں کلاس ثالث کی خوبیوں پر تبصرہ کرے۔"]}]}},"5":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch5-exercise-1",8],["civ12-ch5-exercise-1",9]],"inline":1,"s":["انٹرنیٹ نے دنیا کے ہر حصے کو آپس میں جوڑ دیا ہے، اسی لیے اسے ورلڈ وائڈ ویب (WWW) کہا جاتا ہے۔"],"c":1},{"q":[["civ12-ch5-exercise-1",10],["civ12-ch5-exercise-1",11]],"inline":1,"s":["انٹرنیٹ پر ہر قسم کی معلومات اور ویب سائٹس موجود ہیں؛ کمپیوٹر اور انٹرنیٹ ہو تو دنیا آپ کی میز پر ہے۔"],"c":2},{"q":[["civ12-ch5-exercise-1",12],["civ12-ch5-exercise-1",13]],"inline":1,"s":["کثیر القومی ممالک میں وحدانی طرزِ حکومت ناکام رہتا ہے؛ ملائیشیا، بھارت اور امریکہ نے معیاری وفاقی نظام سے کثیر القومی مسئلہ حل کیا۔"],"c":3},{"q":[["civ12-ch5-exercise-1",14],["civ12-ch5-exercise-1",15]],"inline":1,"s":["جمع شدہ اور ترتیب دیا ہوا مواد طویل محنت کا نتیجہ ہوتا ہے؛ اسے محفوظ رکھنا ضروری ہے۔"],"c":0},{"q":[["civ12-ch5-exercise-1",16],["civ12-ch5-exercise-1",17]],"inline":1,"s":["کسی بھی سرکاری اعلان کو بھی بلیٹن کہتے ہیں؛ بلیٹن ایک موضوعاتی خبر ہوتی ہے۔"],"c":2}],"objective":[{"q":[["civ12-ch5-exercise-1",2]],"s":["تازہ ترین","دوسرے روایتی ذرائع سے بھی معلومات مل سکتی ہیں مگر انٹرنیٹ سے حاصل ہونے والی معلومات تازہ ترین ہوتی ہیں۔"],"a":"تازہ ترین"},{"q":[["civ12-ch5-exercise-1",3]],"s":["مستند (قابلِ اعتماد)","معلومات مختلف غیر جانبدار اور قابلِ اعتماد ذرائع سے حاصل کر کے جمع کی جاتی ہیں۔"],"a":"مستند (قابلِ اعتماد)"},{"q":[["civ12-ch5-exercise-1",4]],"s":["سرچ انجن","کمپیوٹر انٹرنیٹ پر کئی سرچ انجن ہیں (گوگل، یاہو، ایم ایس این، آلٹا وسٹا) جن سے ویب سائٹ کا پتا اور مطلوبہ معلومات حاصل ہوتی ہیں۔"],"a":"سرچ انجن"},{"q":[["civ12-ch5-exercise-1",5]],"s":["انٹرنیٹ","آج کمپیوٹر اور انٹرنیٹ کے استعمال کے بغیر علم نامکمل ہے کیونکہ زندگی کے ہر شعبے میں کمپیوٹر کو کلیدی حیثیت حاصل ہو گئی ہے۔"],"a":"انٹرنیٹ"},{"q":[["civ12-ch5-exercise-1",6]],"s":["محنت","جمع شدہ اور ترتیب دیا ہوا مواد طویل محنت کا نتیجہ ہوتا ہے۔"],"a":"محنت"},{"q":[["civ12-ch5-exercise-1",19]],"tf":"tf","s":["غلط۔ انٹرنیٹ کا مطلب \"مچھلی پکڑنے کا جال\" نہیں؛ یہ کمپیوٹروں کا عالمی جال (نیٹ ورک) ہے جو دنیا کے ہر حصے کو مکڑی کے جالے کی طرح آپس میں جوڑتا ہے (ورلڈ وائڈ ویب)۔"],"c":1},{"q":[["civ12-ch5-exercise-1",20]],"tf":"tf","s":["غلط۔ انٹرنیٹ پر حکومت کی ہر اہم دستاویز موجود ہے، مثلاً 1973ء کا آئین، اس کی ترامیم اور بجٹ۔"],"c":1},{"q":[["civ12-ch5-exercise-2",0]],"tf":"tf","s":["صحیح۔ گوگل سرچ طلبہ کے لیے بہت مفید ہے؛ اس سے مطلوبہ ویب سائٹ یا موضوع کی معلومات فوراً سامنے آ جاتی ہیں۔"],"c":0},{"q":[["civ12-ch5-exercise-2",1]],"tf":"tf","s":["غلط۔ انٹرنیٹ سے مواد ڈاؤن لوڈ کرتے وقت کاپی رائٹ کی بہت اہمیت ہے؛ اجازت کے بغیر ڈاؤن لوڈ کرنے پر قانونی کارروائی ہو سکتی ہے۔"],"c":1},{"q":[["civ12-ch5-exercise-2",2]],"tf":"tf","s":["صحیح۔ جمع شدہ معلومات کو کئی معیارات کی روشنی میں ترتیب دیا جاتا ہے — تحریری، صوتی و تصویری اور کمپیوٹر معلومات الگ الگ۔"],"c":0},{"q":[["civ12-ch5-exercise-2",3]],"tf":"tf","s":["غلط۔ مسائل کو سمجھنے اور حل کرنے کے لیے معلومات جمع کرنا بہت اہم ہے؛ اسی کی بنیاد پر دلائل، نتائج اور حل تک پہنچا جاتا ہے۔"],"c":1},{"q":[["civ12-ch5-exercise-2",4]],"tf":"tf","s":["صحیح۔ آزاد میڈیا جمہوریت کا دل ہے؛ یہ حکومت اور عوام کے درمیان رابطے کا ذریعہ ہے۔"],"c":0}],"shortQuestions":[{"q":[["civ12-ch5-exercise-2",6]],"s":["ویب سائٹ انٹرنیٹ پر کسی فائل (یا صفحات کے مجموعے) کا پتا ہے جس کے ذریعے اس تک پہنچا جا سکتا ہے۔","دنیا بھر کے ادارے اپنی ویب سائٹس بناتے ہیں جو اکثر قیمتی معلومات مفت فراہم کرتی ہیں؛ ویب سائٹ کا استعمال ایک جدید لائبریری کے استعمال جیسا ہے۔"]},{"q":[["civ12-ch5-exercise-2",7]],"s":["WWW کا مطلب ورلڈ وائڈ ویب ہے۔","یہ اس معنی میں استعمال ہوتا ہے کہ انٹرنیٹ کے ذریعے دنیا کا ہر حصہ مکڑی کے جالے کی طرح آپس میں جڑا ہوا ہے؛ یہ انٹرنیٹ پر موجود ویب سائٹس اور صفحات کا عالمی نظام ہے جن تک کہیں سے بھی رسائی ہو سکتی ہے۔"]},{"q":[["civ12-ch5-exercise-2",8]],"s":["کمپیوٹر اور انٹرنیٹ آن کر کے پہلے گوگل (یا کوئی سرچ انجن) کھولیں، پھر مطلوبہ ویب سائٹ کا پتا یا مطلوبہ موضوع لکھیں۔","نتائج سکرین پر آ جائیں گے؛ مطلوبہ ویب سائٹ کھول کر لیکچرز، کتب، مضامین وغیرہ ایک ایک کر کے کھولیں، پڑھیں اور کاپی رائٹ کا خیال رکھتے ہوئے غیر جانبدار و مستند مواد فائل میں محفوظ کر لیں۔"]},{"q":[["civ12-ch5-exercise-2",9]],"s":["انٹرنیٹ نہ ہوتا تو معلومات جمع کرنا طویل، مہنگا اور مشکل عمل ہوتا؛ مثلاً مختلف ممالک کے آئین حاصل کرنے کے لیے کئی سفارت خانوں سے رابطہ کرنا پڑتا۔","لائبریریوں، دفاتر اور ماہرین کے پاس خود جانا پڑتا، تازہ ترین معلومات بروقت نہ ملتیں اور وقت و سرمایہ زیادہ صرف ہوتا۔"]},{"q":[["civ12-ch5-exercise-2",10]],"s":["غربت کے خاتمے کی تجاویز: صنعتوں کا قیام تاکہ روزگار بڑھے؛ چھوٹے کاروبار کے لیے آسان قرضے؛ فنی تعلیم اور ہنر کی تربیت۔","آبادی پر کنٹرول؛ زراعت کی ترقی اور کسانوں کی مدد؛ زکوٰۃ و عشر اور سماجی تحفظ کے پروگرام (جیسے بے نظیر انکم سپورٹ)؛ بدعنوانی کا خاتمہ اور وسائل کی منصفانہ تقسیم؛ تعلیم کو عام کرنا۔"]}],"longQuestions":[{"q":[["civ12-ch5-exercise-2",12]],"s":["ویب سائٹ انٹرنیٹ پر کسی فائل کا پتا ہے؛ کسی بھی موضوع پر معلومات کے لیے ویب سائٹ پر جائیں — اکثر ویب سائٹس قیمتی معلومات مفت دیتی ہیں اور کتب، رسائل، اخبارات اور میڈیا مشہور ویب سائٹس کے نام سے موجود ہیں۔","طریقہ: (1) کمپیوٹر اور انٹرنیٹ آن کریں؛ (2) سرچ انجن (گوگل، یاہو، ایم ایس این، آلٹا وسٹا) کھولیں؛ (3) مطلوبہ ویب سائٹ کا پتا یا موضوع لکھیں؛ (4) نتائج میں سے مطلوبہ ویب سائٹ کھولیں۔","(5) سکرین پر آنے والے لیکچرز، کتب، تقاریر، مضامین اور مباحثے ایک ایک کر کے کھولیں اور ضرورت کے مطابق پڑھیں یا ڈاؤن لوڈ کریں؛ (6) بہترین مواد ایک فائل میں محفوظ کریں تاکہ اطمینان سے پڑھ سکیں اور توجہ موضوع پر رہے۔","احتیاط: کاپی رائٹ کی خلاف ورزی نہ ہو — بعض چیزیں صرف پڑھی جا سکتی ہیں، ڈاؤن لوڈ کی اجازت نہیں؛ مواد غیر جانبدار اور مستند ذرائع سے ہو۔","طلبہ ویب سائٹس سے سرکاری دستاویزات (آئین 1973ء، ترامیم، بجٹ) بھی پڑھ سکتے ہیں؛ اس سہولت کو مثبت، تخلیقی اور مؤثر طریقے سے استعمال کرنا چاہیے۔"]},{"q":[["civ12-ch5-exercise-2",13]],"s":["معلومات کا حصول: مشاہدہ، انٹرویو، سوالنامہ، دستاویزات کا مطالعہ اور انٹرنیٹ (ویب سائٹس) سے کسی خاص موضوع پر معلومات جمع کی جاتی ہیں؛ تحریری معلومات فائل میں، صوتی و تصویری برقی آلات میں اور انٹرنیٹ کی معلومات کمپیوٹر میں محفوظ کی جاتی ہیں۔","ترتیب: جمع شدہ معلومات کو کئی معیارات کی روشنی میں ترتیب دیا جاتا ہے، پھر غور سے پڑھ کر نتیجہ اخذ کیا جاتا ہے کہ زیرِ بحث مسئلے کو سمجھنے اور حل کرنے میں کیا نتیجہ نکلتا ہے؛ نتیجہ نہ نکلے تو معلومات جمع کرنے میں غلطی ہوئی ہوتی ہے۔","دلیل سازی: مطالعے کی بنیاد پر دلیل قائم کرنا — مثلاً ملک \"الف\" میں سیاسی عدم استحکام کی بنیادی وجہ کیا ہے؟ سیاست دانوں کے انٹرویو، مشاہدہ، کتب، ڈائریاں، سوالنامے اور انٹرنیٹ سے معلومات لے کر دلیل بنائی گئی کہ وجہ کثیر القومی مسئلہ اور وحدانی طرزِ حکومت ہے۔","دلائل کی جانچ: اب ایسی حقیقی معلومات جمع کی جاتی ہیں جو دلیل سے مطابقت رکھیں — دیکھا جائے کہ دنیا میں اس کی کوئی مثال ہے؛ ملائیشیا، بھارت اور امریکہ کے آئین و سیاسی تاریخ کے مطالعے سے معلوم ہوا کہ انہوں نے معیاری وفاقی نظام سے مسئلہ حل کیا۔","یوں دلیل کو حقیقی معلومات سے ثابت کرنے سے غلطی کی گنجائش نہیں رہتی اور تحقیق کا ثمر حاصل ہوتا ہے؛ انٹرنیٹ نے یہ کام بہت آسان بنا دیا ہے۔"]},{"q":[["civ12-ch5-exercise-2",14]],"s":["معلومات اور خبروں کی اشاعت کے اہم طریقے:","(1) نیوز لیٹر: کسی خاص گروہ کی دلچسپی سے متعلق شائع شدہ معلومات یا خبریں جو معاشرے یا ادارے کے اراکین اور ملازمین میں تقسیم کی جاتی ہیں۔","(2) بلیٹن بورڈ: کوئی نوٹس یا معلومات بورڈ پر آویزاں کرنا تاکہ بہت سے لوگ جان لیں، مثلاً کالجوں کے نوٹس بورڈ پر داخلے یا میرٹ لسٹ؛ بلیٹن موضوعاتی خبر یا سرکاری اعلان بھی ہوتا ہے۔","(3) میڈیا: پرنٹ میڈیا (اخبارات، رسائل، کتب) اور الیکٹرانک میڈیا (ریڈیو، ٹیلی وژن)؛ آزاد میڈیا جمہوریت کا دل اور حکومت و عوام کے درمیان رابطے کا ذریعہ ہے۔","(4) الیکٹرانک ڈیٹا بیس: جدید طریقہ — معلومات کمپیوٹر میں جمع (ڈیٹا بیس) کر کے ای میل اور ویب سائٹس کے ذریعے پھیلائی جاتی ہیں۔"]}],"activities":[{"q":[["civ12-ch5-exercise-2",16]],"s":["پالیسی پیپر کی تیاری: کلاس کو گروپوں میں تقسیم کیا جائے؛ ہر گروپ ایک مسئلہ (مثلاً غربت، امتحانی نظام، آبادی، لوڈشیڈنگ) منتخب کرے۔","پالیسی پیپر کے چار حصے: (1) مسئلے کی نشان دہی اور اہمیت؛ (2) تین یا چار ممکنہ حل؛ (3) ہر حل کے فوائد و نقصانات کا تنقیدی جائزہ؛ (4) بہترین حل کی سفارش۔ آخر میں ہر گروپ اپنا پیپر کلاس میں پیش کرے۔"]},{"q":[["civ12-ch5-exercise-2",17]],"s":["مضمون نویسی کا مقابلہ — \"کمپیوٹر اور انٹرنیٹ کے فوائد و نقصانات\": فوائد — فوری معلومات، تعلیم و تحقیق، رابطہ، کاروبار، سرکاری دستاویزات تک رسائی؛ نقصانات — وقت کا ضیاع، غلط معلومات، اخلاقی برائیاں، سائبر جرائم، صحت پر اثرات، کاپی رائٹ کی خلاف ورزی؛ نتیجہ — مثبت اور ذمہ دارانہ استعمال۔"]},{"q":[["civ12-ch5-exercise-2",18]],"s":["انٹرنیٹ کے ماہر کو مدعو کر کے سوالات: تعلیم کے لیے اہم ویب سائٹس کون سی ہیں؟ مستند معلومات کی پہچان کیسے کریں؟ سرچ انجن کا مؤثر استعمال کیسے ہو؟ کاپی رائٹ اور آن لائن تحفظ (پاس ورڈ، ذاتی معلومات) کا خیال کیسے رکھیں؟ طلبہ جوابات نوٹ کر کے مختصر رپورٹ تیار کریں۔"]}]}},"6":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch6-exercise-1",8],["civ12-ch6-exercise-1",9]],"inline":1,"s":["جولائی 1972ء میں بھارت اور پاکستان کے درمیان شملہ میں امن معاہدہ (شملہ معاہدہ) ہوا۔"],"c":0},{"q":[["civ12-ch6-exercise-1",10],["civ12-ch6-exercise-1",11]],"inline":1,"n":"یہ معلومات سبق کے دستیاب (پڑھنے کے قابل) صفحات میں موجود نہیں؛ جواب عمومی معلومات پر مبنی ہے کہ اسٹیل ملز روس کے تعاون سے بنی اور اس کی توسیع بھی روس سے طے ہوئی۔","s":["کراچی (پاکستان) اسٹیل ملز سابق سوویت یونین (روس) کے تعاون سے تعمیر ہوئی تھی اور اس کی توسیع کے لیے بھی روس نے ایک ارب ڈالر کی فراہمی کی۔"],"c":3},{"q":[["civ12-ch6-exercise-1",12],["civ12-ch6-exercise-1",13]],"inline":1,"s":["مسلم لیگ کی حکومت نے پہلی بار اسٹیٹ بینک آف پاکستان کو خود مختاری دی۔"],"c":2},{"q":[["civ12-ch6-exercise-1",14],["civ12-ch6-exercise-1",15]],"inline":1,"s":["ذرائع ابلاغ (خصوصاً نجی چینلوں) نے ہر شعبے میں لوگوں کی بیداری میں کمال کی حد تک کردار ادا کیا، جیسے وکلا تحریک میں۔"],"c":0},{"q":[["civ12-ch6-exercise-1",16],["civ12-ch6-exercise-1",17]],"inline":1,"s":["معاشرے میں لوگوں کو برداشت، قبولیت (دوسروں کو تسلیم کرنا) اور رواداری سکھانا ہوگی تاکہ امن قائم ہو۔"],"c":2}],"objective":[{"q":[["civ12-ch6-exercise-1",2]],"s":["مفادات","سیاسی جماعتیں عوامی خواہشات اور مفادات کی ترجمان اور محافظ ہیں۔"],"a":"مفادات"},{"q":[["civ12-ch6-exercise-1",3]],"s":["منشور","ووٹ ہمیشہ کسی جماعت کا منشور یا پروگرام دیکھ کر دینا چاہیے۔"],"a":"منشور"},{"q":[["civ12-ch6-exercise-1",4]],"s":["انٹرنیٹ","جدید سماجی تحریکیں اب جدید ٹیکنالوجی اور انٹرنیٹ استعمال کر رہی ہیں تاکہ عالمی سطح پر لوگوں کو متحرک کیا جا سکے۔"],"a":"انٹرنیٹ"},{"q":[["civ12-ch6-exercise-1",5]],"s":["جمہوری","آزاد عدلیہ ہی ایک جمہوری اور فلاحی نظام کے قیام میں اہم کردار ادا کرتی ہے۔"],"a":"جمہوری"},{"q":[["civ12-ch6-exercise-1",6]],"s":["فرائض","لوگ حقوق کی بات کرتے ہیں مگر اپنے فرائض سے منہ موڑ لیتے ہیں؛ حقوق و فرائض میں توازن ضروری ہے۔"],"a":"فرائض"},{"q":[["civ12-ch6-exercise-1",19]],"tf":"tf","s":["غلط۔ جماعت کا آئین صرف جماعت کی ساخت، عہدے داروں کے انتخاب اور اختیارات کی تقسیم بتاتا ہے، جبکہ قومی آئین پوری ریاست، حکومت اور شہریوں کے حقوق و فرائض کا تعین کرتا ہے؛ دونوں میں نمایاں فرق ہے۔"],"c":1},{"q":[["civ12-ch6-exercise-1",20]],"tf":"tf","s":["غلط۔ اگلے انتخابات سے پہلے یہ دیکھنا بہت ضروری ہے کہ حکمران جماعت نے اپنے زیادہ تر وعدوں پر عمل کیا یا نہیں، اسی کی بنیاد پر ووٹ کا فیصلہ ہونا چاہیے۔"],"c":1},{"q":[["civ12-ch6-exercise-1",21]],"tf":"tf","s":["غلط۔ مستحکم سیاسی نظام کے لیے حزبِ اختلاف کا وجود انتہائی اہم ہے؛ یہ حکومت کو اس کا منشور اور وعدے یاد دلاتی اور اسے حدود میں رکھتی ہے۔"],"c":1},{"q":[["civ12-ch6-exercise-1",22]],"tf":"tf","s":["غلط۔ سیاسی جماعت اقتدار کے حصول کے لیے منظم گروہ ہے، جبکہ سماجی تحریک زندگی میں نیا نظام لانے یا تبدیلی کی اجتماعی کوشش ہے جو اقتدار کی امیدوار نہیں ہوتی۔"],"c":1},{"q":[["civ12-ch6-exercise-1",23]],"tf":"tf","s":["صحیح۔ صنعتی ترقی نے بہت سی تنظیموں اور تحریکوں کو جنم دیا؛ مزدوروں نے اپنے حقوق کے لیے آواز اٹھائی اور تحریکوں کی صورت اختیار کی۔"],"c":0},{"q":[["civ12-ch6-exercise-1",24]],"tf":"tf","s":["صحیح۔ موجودہ عالمی مسائل (افغان جنگ وغیرہ) کی وجہ سے پاکستان انتہا پسندی کا شکار ہے۔"],"c":0},{"q":[["civ12-ch6-exercise-1",25]],"tf":"tf","s":["غلط۔ مسائل بندوق سے نہیں بلکہ عقل اور مذاکرات سے حل ہوتے ہیں؛ ہر جنگ کے بعد آخرکار بات چیت ہی کرنا پڑتی ہے۔"],"c":1},{"q":[["civ12-ch6-exercise-2",0]],"d":"civ12-ch6-match","s":["درست جوڑ:","سیاسی — ثقافت۔","عوامی — شعور۔","ہنگامی — حالات۔","حقوق — و فرائض۔","سماجی — تغیر۔","فوجی — آمریت۔","جمہوری — نفسیات۔","انتہا — پسندی۔"]}],"shortQuestions":[{"q":[["civ12-ch6-exercise-2",2]],"s":["سیاسی جماعت لوگوں کا ایک منظم اجتماع ہے جو سیاسی اقتدار کے حصول کے لیے سرگرم رہتا ہے۔","پروفیسر بختیار کے مطابق: سیاسی جماعت ایک منظم انسانی گروہ ہے جو آئین، منشور، رضاکاروں اور قیادت پر مبنی ہوتا ہے اور آئینی طریقوں سے حکومت حاصل کر کے اپنے منشور کو عملی شکل دیتا ہے۔ (لارڈ برائس: سیاسی مقاصد کے حصول کے لیے رضاکارانہ طور پر متحد افراد کا اجتماع۔)"]},{"q":[["civ12-ch6-exercise-2",3]],"s":["ووٹ ہمیشہ کسی جماعت کے منشور یا پروگرام کو دیکھ کر دینا چاہیے۔","ساتھ یہ بھی دیکھا جائے کہ پچھلی حکومت میں اس جماعت نے اپنے وعدوں پر کتنا عمل کیا؛ امیدوار کا کردار، اہلیت اور دیانت داری بھی معیار ہونی چاہیے، نہ کہ برادری، تعصب یا ذاتی مفاد۔"]},{"q":[["civ12-ch6-exercise-2",4]],"s":["فوجی آمریت سے مراد وہ حکومت ہے جو فوج کا سربراہ منتخب سول حکومت کو ہٹا کر قائم کرے؛ اس میں آئین معطل یا منسوخ کر کے مارشل لا نافذ کیا جاتا ہے۔","تمام اختیارات ایک فرد یا فوجی ٹولے کے ہاتھ میں مرکوز ہوتے ہیں، سیاسی سرگرمیوں اور پریس پر پابندیاں ہوتی ہیں (مثلاً ایوب، ضیاء اور مشرف کے ادوار)۔"]},{"q":[["civ12-ch6-exercise-2",5]],"s":["سماجی تحریک اجتماعی رویے کی ایک بڑی صورت ہے؛ یہ زندگی میں نیا نظام قائم کرنے کی اجتماعی کوشش ہے، جیسے حقوقِ نسواں کی تحریک۔","ہارٹن اور ہنٹ کے مطابق: سماجی تحریک کسی تبدیلی کو آگے بڑھانے یا اس کی مزاحمت کی اجتماعی کوشش ہے۔"]},{"q":[["civ12-ch6-exercise-2",6]],"s":["سماجی تحریکوں کی اقسام: سیاسی تحریکیں، ثقافتی تحریکیں، عوامی حقوق کی تحریکیں، اصلاحی تحریکیں، مزاحمتی تحریکیں، مذہبی تحریکیں اور انقلابی سماجی تحریکیں۔"]}],"longQuestions":[{"q":[["civ12-ch6-exercise-2",8]],"s":["سیاسی جماعتیں جمہوریت اور سیاسی نظام کا لازمی حصہ ہیں؛ یہی سیاسی نظام میں حرکت پیدا کرتی ہیں۔","ہر جماعت کا تحقیقی سیل قومی مسائل پر معلومات جمع کر کے ان کا حل منشور کی صورت میں پیش کرتا ہے جسے عوام تک پہنچایا جاتا ہے؛ جماعتیں عوامی خواہشات اور مفادات کی ترجمان اور محافظ ہیں اور عوامی مشکلات حکومتی اداروں تک پہنچاتی ہیں۔","انتخابات میں عوام جماعتوں کو مینڈیٹ دیتے ہیں؛ جیتنے والی جماعت حکومت بناتی ہے اور منشور پر عمل کرتی ہے۔","حزبِ اختلاف حکومت کو اس کے وعدے یاد دلاتی، تنقید کرتی اور حدود میں رکھتی ہے؛ جماعتیں حکومت اور عوام کے درمیان دو طرفہ رابطے کا ذریعہ ہیں اور عوام کی سیاسی تربیت کرتی ہیں۔","المیہ یہ ہے کہ ترقی پذیر ممالک میں نہ حکومت حزبِ اختلاف کو برداشت کرتی ہے نہ حزبِ اختلاف اپنا جائز کردار ادا کرتی ہے؛ اگر جماعتیں اصولوں پر قائم ہوں تو وہ جمہوریت کی روح ثابت ہوتی ہیں اور اس کے استحکام کا باعث بنتی ہیں۔"]},{"q":[["civ12-ch6-exercise-2",9]],"s":["طریقہ: حکمران جماعت کا تحریری منشور (پارٹی دفاتر، اخبارات یا ویب سائٹ سے) لے کر اس کے ہر نکتے کا جماعت کی حکومتی کارکردگی سے موازنہ کیا جائے؛ یہ دیکھا جائے کہ زیادہ تر وعدے پورے ہوئے یا نہیں، کیونکہ کوئی جماعت سو فیصد منشور پر عمل نہیں کر سکتی۔","مثال — پاکستان پیپلز پارٹی (بے نظیر بھٹو): منشور میں خود مختاری، ترقی، اختیارات کی نچلی سطح پر منتقلی، مقامی حکومتیں، بچوں، مزدوروں، خواتین اور اقلیتوں کے حقوق، بدعنوانی و غربت کا خاتمہ، صنعتی ترقی، جاگیرداری کا خاتمہ، سب کے لیے تعلیم اور طلبہ یونینوں کی بحالی شامل تھے۔","کارکردگی: خواتین کو نمائندگی، بے نظیر انکم سپورٹ پروگرام (2008ء کے بعد)، اٹھارویں ترمیم کے ذریعے صوبائی خود مختاری اور اختیارات کی منتقلی جیسے وعدے پورے ہوئے۔","تاہم بدعنوانی کے الزامات، غربت اور توانائی کا بحران برقرار رہا اور شرحِ خواندگی کا ہدف حاصل نہ ہو سکا؛ جاگیرداری کا خاتمہ بھی نہ ہوا۔","نتیجہ: جماعت نے بعض اہم وعدے پورے کیے مگر کئی بنیادی نکات پر عمل ادھورا رہا؛ اسی جائزے کی روشنی میں اگلے انتخابات میں ووٹ کا فیصلہ کرنا چاہیے۔"]},{"q":[["civ12-ch6-exercise-2",10]],"s":["سیاسی جماعت سیاسی نظام کا باقاعدہ اور اہم ترین حصہ ہے اور اس کے اندر ذیلی نظام کے طور پر کام کرتی ہے؛ ہر جماعت نیچے سے اوپر تک منظم ہوتی ہے، اس کے عہدے دار، جھنڈا، نظریہ اور نعرہ ہوتا ہے۔ عموماً جماعت چار عناصر سے بنتی ہے جو اس کے اتحاد کا باعث ہیں:","1۔ منشور: ملک کے فوری اور سنگین مسائل کو مدِنظر رکھ کر تیار کیا گیا پروگرام جسے قیادت منظور کرتی ہے؛ اسی کی بنیاد پر جماعت انتخاب لڑتی اور حکومت میں آ کر پالیسی اور قانون سازی کرتی ہے۔","2۔ آئین: وہ دستاویز جو جماعت کی ساخت، عہدے داروں کے انتخاب اور جماعت کے اندر اختیارات کی درجہ بدرجہ تقسیم بتاتی ہے؛ رسمی آئین والی جماعتوں کا احترام نہیں ہوتا۔","3۔ رضاکار: اراکین کے بغیر جماعت کھوکھلا ڈھانچہ ہے؛ رضاکار بغیر تنخواہ کے کام کرتے، چندہ دیتے، پروگرام عوام تک پہنچاتے، قیادت کا انتخاب کرتے اور انتخابات میں سرگرم حصہ لیتے ہیں۔","4۔ قیادت: کوئی منظم گروہ قیادت کے بغیر مکمل نہیں؛ معروف شخصیات پر مشتمل منتخب قیادت جماعت کو چلاتی ہے اور عوام اس کے کردار کو پرکھ کر جماعت کا مقام طے کرتے ہیں۔"]},{"q":[["civ12-ch6-exercise-2",11]],"s":["پاکستان اسلام، جمہوریت اور عوامی فلاح کے لیے قائم ہوا؛ ان مقاصد کے حصول کے لیے بہت سی سماجی تحریکیں پیدا ہوئیں — ٹریڈ یونینز، وکلا، اساتذہ، کسانوں، خواتین و بچوں کے حقوق، صحافیوں، طلبہ اور فلاحی اداروں کی تنظیمیں۔","انہوں نے بیس کروڑ سے زائد عوام کی آواز ایوانوں تک پہنچائی، اپنے زیادہ تر مطالبات منوائے اور حکومتوں کو اسلامی، جمہوری اور فلاحی قانون سازی پر مجبور کیا (شرعی قوانین، خواتین و بچوں کے حقوق کے قوانین)۔","خواتین کی تحریک (ویمن ایکشن فورم، 1981ء سے فعال): خواتین پر ظلم کے خلاف آگاہی اور مفت قانونی امداد؛ آج خواتین کو ایوانوں میں بھرپور نمائندگی حاصل ہے۔","وکلا تحریک (2007ء): جنرل مشرف کے 9 مارچ 2007ء کے آمرانہ فیصلے کے خلاف تحریک جس کے نتیجے میں اعلیٰ عدلیہ کے جج بحال ہوئے اور عدلیہ آزاد ہوئی — آزاد عدلیہ جمہوری اور فلاحی نظام کی بنیاد ہے۔","یوتھ نیشنل فلیگ موومنٹ (13 مئی 2009ء) جیسی تحریکوں نے حب الوطنی بیدار کی؛ فلاحی ادارے (ایدھی وغیرہ) عوامی فلاح میں کردار ادا کر رہے ہیں۔ یوں سماجی تحریکیں پاکستان کو حقیقی معنوں میں اسلامی، جمہوری اور فلاحی ریاست بنانے میں اہم ہیں۔"]},{"q":[["civ12-ch6-exercise-2",12]],"s":["1۔ سیاسی وجوہات: غیر مستحکم سیاسی حالات اور طویل فوجی آمریت؛ سیاسی سرگرمیوں پر پابندیوں کے خلا کو سماجی تحریکوں نے پُر کیا؛ جمہوریت کی بحالی کے لیے تحریکیں۔ عدلیہ کی آزادی پر حملے — ہنگامی حالت اور ججوں کی برطرفی — نے وکلا تحریک کو جنم دیا جسے سیاسی جماعتوں، صحافیوں، این جی اوز اور میڈیا نے سہارا دیا۔","2۔ معاشی وجوہات: امیر و غریب کا بڑھتا فرق — سوشلسٹ طرز کی تحریکیں؛ صنعتی ترقی سے مزدور تنظیمیں اور پیشہ ورانہ گروہوں کی تحریکیں۔","3۔ مذہبی وجوہات: مذہبی احیا اور آئینی اصلاحات کے لیے تحریکیں — تحریکِ نظامِ مصطفیٰ ﷺ، تحریکِ اسلامی، سنی اتحاد تحریک وغیرہ۔","4۔ دیگر وجوہات: نسلی، لسانی اور انسانی حقوق کے مسائل؛ محرومی کا شکار گروہوں کی تحریکیں؛ دباؤ اور مفاداتی گروہوں کی سرگرمیاں۔","عمومی عوامل: تعلیم، شہری زندگی، انسانی حقوق کا شعور، اظہارِ رائے کی آزادی، سیاسی بیداری اور ذرائع ابلاغ (انٹرنیٹ) نے بھی سماجی تحریکوں کو فروغ دیا۔"]},{"q":[["civ12-ch6-exercise-2",13]],"s":["تعلیم کا فروغ: بدامنی کی سب سے بڑی وجہ جہالت ہے؛ مقامی سطح پر تعلیمی مہم، فارغ اوقات میں مفت ٹیوشن، والدین کی ترغیب اور غریب ذہین طلبہ کی مالی مدد۔","عدم تشدد کی تبلیغ: معاشرے کے تعلیم یافتہ نوجوان عدم تشدد سے معاشرے کی خدمت کرنے والی عظیم شخصیات کے نظریات اپنائیں؛ برداشت، قبولیت اور رواداری سکھائی جائے۔","مسائل جذبات سے نہیں عقل اور مکالمے سے حل کیے جائیں؛ جرگہ، مصالحتی کمیٹیاں اور ثالثی کو فروغ دیا جائے۔","حقوق و فرائض سے آگاہی اور ان میں توازن — لوگ صرف حقوق کی نہیں فرائض کی بھی پاسداری کریں۔","امن کا عزم اور طویل المدتی حکمتِ عملی: اگر کمیونٹی کے زیادہ تر لوگ عزم کر لیں تو ماحول پرامن بنایا جا سکتا ہے؛ مساجد، سکولوں اور میڈیا کے ذریعے امن کا پیغام، کھیلوں اور مشترکہ سرگرمیوں سے بھائی چارہ۔"]}],"activities":[{"q":[["civ12-ch6-exercise-2",15]],"s":["اس باب پر کوئز: مثلاً سیاسی جماعت کے چار عناصر؟ (منشور، آئین، رضاکار، قیادت)؛ وکلا تحریک کب شروع ہوئی؟ (2007ء)؛ یوتھ نیشنل فلیگ موومنٹ؟ (13 مئی 2009ء)؛ ویمن ایکشن فورم کس سال سے فعال ہے؟ (1981ء)۔ ٹیموں کے درمیان سوال و جواب کا مقابلہ کرایا جائے۔"]},{"q":[["civ12-ch6-exercise-2",16]],"s":["تقریری مقابلہ — \"پاکستان میں سیاسی جماعتوں کی خوبیاں اور خامیاں\": خوبیاں — عوامی ترجمانی، سیاسی تربیت، جمہوریت کا تسلسل، حکومت کا احتساب؛ خامیاں — موروثی قیادت، اندرونی جمہوریت کی کمی، علاقائی و لسانی سیاست، منشور پر عمل نہ کرنا، اقتدار کی رسہ کشی۔ ججز دلائل اور اندازِ بیان پر نمبر دیں۔"]},{"q":[["civ12-ch6-exercise-2",17]],"s":["گروپوں میں مختلف سیاسی جماعتوں کے منشور کے اہم نکات کے چارٹ: ہر گروپ ایک جماعت کا منشور (ویب سائٹ یا اخبار سے) لے کر تعلیم، صحت، معیشت، خارجہ پالیسی اور حقوق جیسے عنوانات کے تحت نکات لکھے اور کلاس میں پیش کر کے موازنہ کرے۔"]}]}},"7":{"lang":"ur","items":{"objective":[{"q":[["civ12-ch7-exercise-1",2]],"s":["امن","جہاں امن ہوتا ہے وہاں تشدد اور نفرتیں نہیں ہوتیں؛ امن ہی خوشحالی اور ترقی کی بنیاد ہے۔"],"a":"امن"},{"q":[["civ12-ch7-exercise-1",3]],"s":["حقِ خود ارادیت","اقوامِ متحدہ کے منشور میں قوموں کے حقِ خود ارادیت کو تسلیم کیا گیا ہے۔"],"a":"حقِ خود ارادیت"},{"q":[["civ12-ch7-exercise-1",4]],"s":["عدلیہ","پاکستان میں ایک خود مختار اور آزاد عدلیہ کی ضرورت ہے تاکہ سب کو بلا امتیاز انصاف ملے۔"],"a":"عدلیہ"},{"q":[["civ12-ch7-exercise-1",5]],"s":["مساوات","اسلام انسانی مساوات کی تعلیم دیتا ہے؛ جب زندگی کی تمام سرگرمیوں میں مساوات شامل ہو تو مثبت تنوع اور رواداری پیدا ہوتی ہے۔"],"a":"مساوات"},{"q":[["civ12-ch7-exercise-1",7]],"tf":"tf","s":["صحیح۔ پرامن معاشرہ ترقی کی راہ پر گامزن معاشرہ ہے؛ امن کی وجہ سے لوگ اپنی صلاحیتیں ترقی کے لیے استعمال کرتے ہیں۔"],"c":0},{"q":[["civ12-ch7-exercise-1",8]],"tf":"tf","s":["غلط۔ ترقی پذیر اور پسماندہ معاشروں میں تعلیم کی شرح بہت کم ہوتی ہے، اسی لیے وہاں جنگ اور بدامنی کے امکانات زیادہ ہوتے ہیں۔"],"c":1},{"q":[["civ12-ch7-exercise-1",9]],"tf":"tf","s":["غلط۔ جنگوں کے بعد کے واقعات خارجہ پالیسیوں کو متاثر کرتے ہیں — انتقام کے جذبات، نئے اتحاد اور نئی معاشی تنظیمیں جنم لیتی ہیں۔"],"c":1},{"q":[["civ12-ch7-exercise-1",10]],"tf":"tf","s":["غلط۔ پاکستان مذہبی انتہا پسندی اور فرقہ واریت کا شکار ہے؛ برداشت، رواداری اور قبولیت کی کمی ہے۔"],"c":1},{"q":[["civ12-ch7-exercise-2",0]],"tf":"tf","s":["غلط۔ سبق کے مطابق تعلیم کو ترجیح دی جائے مگر تعلیم صرف روزگار کے لیے نہیں بلکہ کردار سازی، شعور اور برداشت پیدا کرنے کے لیے ہونی چاہیے۔"],"c":1},{"q":[["civ12-ch7-exercise-2",1]],"tf":"tf","s":["صحیح۔ عالمی سطح پر ہر قومیت کو اپنی خواہشات کے مطابق جینے اور اپنی انفرادیت برقرار رکھنے کا حق ہے؛ کسی کی انفرادیت ختم کرنا انصاف کا تقاضا نہیں۔"],"c":0},{"q":[["civ12-ch7-exercise-2",2]],"tf":"tf","s":["غلط۔ معاشی طبقات کا فرق کم کرنے کے لیے دولت کا ارتکاز نہیں بلکہ وسائل اور دولت کی منصفانہ تقسیم ضروری ہے۔"],"c":1}],"shortQuestions":[{"q":[["civ12-ch7-exercise-2",4]],"s":["امتیاز (تفریق) سے مراد کسی فرد یا گروہ کے ساتھ نسل، زبان، عمر، مذہب یا جنس کی بنیاد پر تعصب، بدنیتی اور شک کی وجہ سے دوسروں کے مقابلے میں غیر منصفانہ سلوک کرنا ہے (انکارٹا)۔","یہ ایک نفسیاتی اور سماجی عمل ہے جو ہر معاشرے میں کم یا زیادہ پایا جاتا ہے، اور ایک بڑی اخلاقی، مذہبی اور سماجی برائی ہے۔"]},{"q":[["civ12-ch7-exercise-2",5]],"s":["اسلامی تہذیب میں اخوت (بھائی چارہ) اور مساوات کو بنیادی مقام حاصل ہے: ہر مسلمان دوسرے مسلمان کا بھائی ہے؛ کسی عربی کو عجمی پر یا گورے کو کالے پر کوئی فضیلت نہیں سوائے تقویٰ کے۔","اسلام انسانی مساوات کی تعلیم دیتا ہے اور غیر مسلموں کو بھی باعزت مقام دیتا ہے؛ انصاف پر مبنی سلوک سے معاشرے میں رواداری اور مثبت تنوع پیدا ہوتا ہے۔"]},{"q":[["civ12-ch7-exercise-2",6]],"s":["رواداری (برداشت) سے مراد دوسروں کے مختلف عقائد، آرا، ثقافت اور طرزِ زندگی کو برداشت کرنا اور ان کا احترام کرنا ہے، چاہے ہم ان سے متفق نہ ہوں۔","رواداری متنوع معاشرے کو جوڑ کر رکھتی ہے؛ اس کے بغیر فرقہ واریت اور تصادم جنم لیتے ہیں۔ اسلام صبر، درگزر، رحم، قبولیت اور انسانی احترام کی تعلیم دیتا ہے؛ نصاب، تعلیم اور میڈیا کے ذریعے رواداری کو فروغ دیا جا سکتا ہے۔"]}],"longQuestions":[{"q":[["civ12-ch7-exercise-2",8]],"s":["پرامن معاشرہ محفوظ معاشرہ ہے جہاں جنگیں اور تنازعات نہیں ہوتے؛ ہر ایک کی جان و مال محفوظ ہوتے ہیں۔","یہ ترقی کی راہ پر گامزن معاشرہ ہے: لوگ اپنی سوچ، توانائی اور سرگرمیاں ترقی کے لیے استعمال کرتے، اعتماد سے کاروبار کرتے اور بچے پرامن ماحول میں تعلیم پاتے ہیں۔","یہ تعلیم یافتہ معاشرہ ہے: شرحِ خواندگی زیادہ، جہالت ختم اور روایتی سوچ میں تبدیلی؛ یہی سماجی تبدیلی معاشروں کو زندہ رکھتی ہے۔","یہ مستحکم، پائیدار اور سدا بہار معاشرہ ہے؛ خوشحالی ہوتی ہے، ہر ایک مطمئن اور خوش ہوتا ہے؛ مذہبی، سیاسی، سماجی اور ثقافتی سرگرمیاں عروج پر ہوتی ہیں۔","امن بہت سی دوسری اچھی سرگرمیوں کا باعث بنتا ہے؛ اسی لیے کہا جا سکتا ہے کہ ایک بہترین معاشرے کی بنیاد امن ہے۔"]},{"q":[["civ12-ch7-exercise-2",9]],"s":["اسلامی تہذیب کی بنیاد توحید، رسالت اور آخرت کے عقائد پر ہے؛ زندگی کا طرز اور سماجی اقدار اسلامی اصولوں پر مبنی ہیں۔","اخوت و مساوات: ہر مسلمان دوسرے کا بھائی؛ رنگ، نسل اور زبان کی بنیاد پر کوئی برتری نہیں؛ معیارِ فضیلت تقویٰ ہے؛ غیر مسلموں کو بھی باعزت مقام۔","عدل و انصاف: ہر کام انصاف پر مبنی؛ کسی کا حق پامال نہ ہو تو جھگڑا نہیں ہوتا؛ قانون کی نظر میں سب برابر۔","اعلیٰ اخلاقی اقدار: تعاون، صبر، امن، ایثار، قربانی، مہربانی، رحم، قبولیت، انسانی احترام، رواداری اور شہری ذمہ داری؛ ذاتی کے بجائے اجتماعی مفاد۔","علم، شرم و حیا، سادگی، حقوق و فرائض میں توازن اور اعتدال؛ ان خصوصیات کی بدولت اسلامی تہذیب تنوع کے باوجود اتحاد اور رواداری پیدا کرتی ہے۔"]},{"q":[["civ12-ch7-exercise-2",10]],"s":["مقامی سطح: جہالت اور تعلیم کی کمی؛ مذہبی فرقہ واریت؛ برداشت، رواداری اور قبولیت کی کمی؛ سیاسی اختلافات میں نظریات کو نیچا دکھانے کے لیے تشدد اور بندوق کا استعمال؛ ذاتی، خاندانی اور قبائلی دشمنیاں، زمین اور جائیداد کے جھگڑے۔","قومی سطح: ایک سے زیادہ نسلوں اور قومیتوں والے ممالک میں تصادم کا امکان زیادہ (مشرقی پاکستان کی علیحدگی)؛ علاقائی مفادات اور وسائل کی غیر منصفانہ تقسیم؛ محرومیاں؛ سیاسی عدم استحکام۔","عالمی سطح: پہلی و دوسری عالمی جنگ، پاک بھارت جنگیں وغیرہ؛ سب سے اہم وجہ قومی مفادات کا حصول — بین الاقوامی معاملات میں ہر چیز بدل سکتی ہے مگر قومی مفاد پر سودے بازی نہیں ہوتی۔","اسلحے کی دوڑ، علاقائی تنازعات، آزادی کی تحریکوں کو کچلنا، حقِ خود ارادیت سے انکار، وسائل پر قبضے کی خواہش، نظریاتی اختلافات اور بڑی طاقتوں کی مداخلت۔","جنگوں کے بعد انتقام کے جذبات مزید جنگوں کا سبب بنتے ہیں؛ اس لیے تمام سطحوں پر تعلیم، انصاف اور مذاکرات ہی جنگوں کی روک تھام کر سکتے ہیں۔"]}],"activities":[{"q":[["civ12-ch7-exercise-2",12]],"s":["امن کی اہمیت پر تقریری مقابلہ — نکات: امن کی تعریف؛ پرامن معاشرے کی خصوصیات (تحفظ، ترقی، تعلیم، استحکام)؛ جنگ کے نقصانات؛ اسلام امن کا دین؛ امن کے قیام میں نوجوانوں کا کردار۔ ججز مواد، دلائل اور اندازِ بیان پر نمبر دیں۔"]},{"q":[["civ12-ch7-exercise-2",13]],"s":["کلاس میں مباحثہ: ہمارے معاشرے میں امتیاز کی مختلف صورتیں — جنس (لڑکیوں کی تعلیم)، نسل و زبان، مذہب و فرقہ، معاشی طبقہ (امیر و غریب)، علاقائیت، معذوری اور عمر کی بنیاد پر امتیاز۔ طلبہ مثالیں دیں اور ان کے خاتمے کی تجاویز بورڈ پر لکھیں (تعلیم، قانون کی عمل داری، اسلامی مساوات)۔"]},{"q":[["civ12-ch7-exercise-2",14]],"s":["مضمون نویسی کا مقابلہ — \"اسلام میں رواداری\": نکات — رواداری کا مفہوم؛ قرآن و سنت میں رواداری (لا اکراہ فی الدین، میثاقِ مدینہ، فتحِ مکہ پر عام معافی، غیر مسلموں کے حقوق)؛ خلفائے راشدین کی مثالیں؛ موجودہ دور میں اس کی ضرورت؛ نتیجہ۔"]}]}},"8":{"lang":"ur","items":{"mcqs":[{"q":[["civ12-ch8-exercise-2",1],["civ12-ch8-exercise-2",2]],"inline":1,"s":["کینیڈا میں ہنگامی حالات کی نقالی (ایمرجنسی سیمولیشن) کا پروگرام شروع کیا گیا ہے تاکہ لوگوں کو حادثات اور آفات سے نمٹنے کی تربیت دی جائے۔"],"c":0},{"q":[["civ12-ch8-exercise-2",3],["civ12-ch8-exercise-2",4]],"inline":1,"s":["عوامی خدمت کے پیغامات میں مزید معلومات کے لیے اپنا پتا یا ٹیلی فون نمبر شامل کیا جا سکتا ہے۔"],"c":3},{"q":[["civ12-ch8-exercise-2",5],["civ12-ch8-exercise-2",6]],"inline":1,"s":["دستخطی مہم میں کارکن شہروں میں دکانوں، پارکوں، بس اسٹاپوں اور سکولوں میں لوگوں کو آمنے سامنے مسئلہ سمجھا کر دستخط لیتے ہیں۔"],"c":2},{"q":[["civ12-ch8-exercise-2",7],["civ12-ch8-exercise-2",8]],"inline":1,"s":["کمیونٹی سروس عموماً رضاکارانہ سرگرمی ہے، اگرچہ بعض لوگ معاوضہ لیتے یا پابند ہو کر بھی یہ کام کرتے ہیں۔"],"c":1},{"q":[["civ12-ch8-exercise-2",9],["civ12-ch8-exercise-2",10]],"inline":1,"s":["آفات سے نمٹنے کا نعرہ \"تیار رہنا\" ہے؛ تیاری ہر قسم کے سانحے کے لیے ہونی چاہیے۔"],"c":3}],"objective":[{"q":[["civ12-ch8-exercise-1",2]],"s":["تربیت","نقالی (سیمولیشن) کے ذریعے سیکھنے کا عمل تربیت میں اہم کردار ادا کرتا ہے؛ اس کا مقصد لوگوں کو متوقع حادثات کے لیے تیار کرنا ہے۔"],"a":"تربیت"},{"q":[["civ12-ch8-exercise-1",3]],"s":["آگاہی (شعور)","دستخطی مہم کا اہم مقصد لوگوں میں کسی مسئلے کے بارے میں آگاہی اور احساس پیدا کرنا اور متعلقہ اداروں پر دباؤ بڑھانا ہے۔"],"a":"آگاہی (شعور)"},{"q":[["civ12-ch8-exercise-1",4]],"s":["سرگرمیوں (ذمہ داریوں)","سانحے کے دوران منتخب ٹیم اپنی تفویض کردہ سرگرمیوں میں مصروف ہو جاتی ہے اور متاثرین کو بہتری کے مواقع فراہم کرتی ہے۔"],"a":"سرگرمیوں (ذمہ داریوں)"},{"q":[["civ12-ch8-exercise-1",5]],"s":["سزا","کچھ لوگوں کو سزا کے طور پر کمیونٹی سروس میں لگایا جاتا ہے، جبکہ بعض یہ خدمات مذہبی جذبے سے انجام دیتے ہیں۔"],"a":"سزا"},{"q":[["civ12-ch8-exercise-1",6]],"s":["ذمہ دار","منصوبہ بندی، تیاری اور نمٹنے کے عمل میں ذمہ دار لوگوں کی موجودگی ضروری ہے تاکہ موقع پر احکامات جاری ہوں اور رقم فراہم کی جا سکے۔"],"a":"ذمہ دار"},{"q":[["civ12-ch8-exercise-2",11]],"d":"civ12-ch8-match","s":["درست جوڑ:","پائیدار — بحالی۔","فعال — شہریت۔","میڈیا — مہم۔","منصوبہ — سازی۔","دستاویزی — پروگرام۔","ہنگامی — صورتِ حال۔","قدرتی — آفات۔"]}],"shortQuestions":[{"q":[["civ12-ch8-exercise-2",13]],"s":["حقیقی دنیا میں ہونے والے واقعات دوبارہ نہیں دکھائے جا سکتے، اس لیے کسی حقیقی چیز، حالت یا عمل کی نقالی کر کے سکھایا جاتا ہے۔","مقصد لوگوں کو متوقع حادثات کے لیے تیار کرنا ہے — مثلاً تیل صاف کرنے کے کارخانے میں مصنوعی آگ لگا کر بجھانے کی مشق؛ اس سے طلبہ اور کارکن عملی زندگی میں فعال کردار ادا کرنے کے قابل ہوتے ہیں۔"]},{"q":[["civ12-ch8-exercise-2",14]],"s":["عوامی خدمت کے پیغامات ٹیلی وژن، ریڈیو اور پرنٹ میڈیا (اخبارات، رسائل، پوسٹرز) کے ذریعے پیش کیے جاتے ہیں؛ آج کل انٹرنیٹ اور سوشل میڈیا بھی استعمال ہوتے ہیں۔"]},{"q":[["civ12-ch8-exercise-2",15]],"s":["دستخطی مہم سے لوگوں میں مسئلے کے بارے میں آگاہی پیدا ہوتی ہے اور متعلقہ اداروں پر دباؤ بڑھتا ہے۔","یہ پرامن اور مؤثر ذریعہ ہے: سیاسی مظاہرے میں شرکا کو مارا یا گرفتار کیا جا سکتا ہے، مگر دستخطی مہم کو دبانا بہت مشکل ہے؛ کم کارکنوں سے زیادہ لوگوں تک بات پہنچتی ہے اور بااختیار لوگوں تک عوام کا مؤقف پہنچتا ہے۔"]},{"q":[["civ12-ch8-exercise-2",16]],"s":["آل پارٹیز حریت کانفرنس نے جموں اور آزاد کشمیر میں دو ہفتے تک دستخطی مہم چلائی تاکہ امریکی صدر باراک حسین اوباما کی توجہ مسئلۂ کشمیر کی طرف مبذول کرائی جائے؛ دستخطوں پر مشتمل دستاویز نئی دہلی میں امریکی سفارت خانے میں یادداشت کے طور پر پیش کی گئی۔","(ایرانی خواتین نے بھی حقوقِ نسواں کے لیے دس لاکھ دستخطوں کی مہم چلائی۔)"]},{"q":[["civ12-ch8-exercise-2",17]],"s":["شعوری سانحات وہ ہیں جو انسان جان بوجھ کر کرتا ہے، مثلاً جنگ، دہشت گردی، قتلِ عام اور دھماکے۔","غیر شعوری سانحات وہ ہیں جو انسان کے ہاتھوں انجانے میں، لاپرواہی، غفلت یا فنی خرابی سے ہوتے ہیں، مثلاً ٹریفک حادثات۔ (ان کے علاوہ قدرتی آفات — زلزلہ، سیلاب، طوفان، وبا — قدرت کی طرف سے آتی ہیں۔)"]}],"longQuestions":[{"q":[["civ12-ch8-exercise-2",19]],"s":["نقالی سے مراد کسی چیز کی خصوصیات کی نقل کر کے پیش کرنا ہے (جیسے اداکاری)؛ کسی حقیقی چیز، حالت، معاملے یا عمل کی نقالی کی جاتی ہے تاکہ اس کے بارے میں سیکھا جا سکے۔","مشکلات: پہلے اس چیز کے بارے میں درست معلومات حاصل کرنا تاکہ اس کا رویہ اور خصوصیات صحیح پیش ہوں؛ ماحول کو کنٹرول میں رکھنا۔","تربیت میں کردار: اس کا مقصد لوگوں کو متوقع سانحات کے لیے تیار کرنا ہے؛ مصنوعی حادثہ پیش کر کے دیکھا جاتا ہے کہ لوگ کیسے ردِعمل دیتے ہیں — مثلاً آئل ریفائنری میں مصنوعی آگ لگا کر بجھانے کی مشق، جو کنٹرول شدہ ماحول میں ہوتی ہے۔","تعلیمی اداروں میں: حقیقی واقعات دوبارہ نہیں دکھائے جا سکتے، اس لیے طلبہ کو نقالی سے تربیت دی جاتی ہے، مثلاً کلاس میں اقوامِ متحدہ کی جنرل اسمبلی یا سلامتی کونسل کا اجلاس منعقد کرنا (صدر کا انتخاب، بحث، سفارشات پر ووٹنگ، مستقل اراکین کا ویٹو)۔","فائدے: عملی مہارت، اعتماد، فیصلہ سازی، ٹیم ورک اور حقیقی حالات میں درست ردِعمل کی صلاحیت پیدا ہوتی ہے۔"]},{"q":[["civ12-ch8-exercise-2",20]],"s":["عوامی خدمت کا پیغام ایک قسم کا اشتہار ہے جو ٹی وی، ریڈیو یا پرنٹ میڈیا کے ذریعے پیش کیا جاتا ہے؛ اس کا مقصد ان مسائل کی نشان دہی ہے جن کے بارے میں عوام کو تعلیم دینا ضروری ہے؛ صحت اور تحفظ اس کے اہم موضوعات ہیں۔","تیاری: سوچیں کہ آپ دنیا کو کیا بتانا چاہتے ہیں اور کون سے آسان الفاظ استعمال کریں گے؛ پیغام مؤثر ہوتا ہے جب پیش کرنے والا رضاکار ہو، مسئلے کی مکمل معلومات ہوں، متوقع ردِعمل واضح ہو اور یہ بڑی میڈیا مہم کا حصہ ہو۔","دورانیہ: 10، 15، 20 یا 30 سیکنڈ جن میں بالترتیب 20–25، 30–35، 40–50 اور 60–75 الفاظ ہوں؛ اسکرپٹ دو کالموں میں — بائیں جانب ہدایات، کیمرہ زاویے اور صوتی اثرات، دائیں جانب مکالمہ؛ آخر میں پتا یا فون نمبر۔","مثال (ریڈیو پیغام، 30 سیکنڈ): ادارہ — ایڈز سے تحفظ کی تنظیم؛ عنوان — ایڈز سے متاثرہ افراد سے ہمدردی کا دن؛ نکات — 20 جون کو یہ دن منایا جائے گا؛ ملک میں لاکھوں افراد اس مرض میں مبتلا ہیں؛ ان سے نفرت نہیں ہمدردی کریں اور احتیاطی تدابیر اپنائیں؛ مزید معلومات کے لیے رابطہ نمبر۔","ایک اور مثال (ٹی وی): \"پانی زندگی ہے — اسے ضائع نہ کریں\" — ٹپکتے نل کا منظر، بچے کا نل بند کرنا اور آخر میں نعرہ اور ادارے کا نام۔"]},{"q":[["civ12-ch8-exercise-2",21]],"s":["آفات کا انتظام وہ عمل ہے جس میں کسی بڑے واقعے یا حادثے سے اس طرح نمٹا جائے کہ عوام اس کے نقصانات سے مکمل بچ جائیں یا نقصان کم سے کم ہو؛ خطرناک صورتحال کو بروقت سمجھنا، شناخت کرنا، درست تعین کرنا اور کم سے کم وقت میں فیصلہ کر کے نمٹنا۔","آفات کی اقسام: قدرتی (زلزلہ، آگ، سیلاب، طوفان، لینڈ سلائیڈنگ، وبا، عمارت کا گرنا) اور انسانی (شعوری — جنگ، دہشت گردی، دھماکے؛ غیر شعوری — ٹریفک حادثات)۔","منصوبہ بندی: بہترین انتظام خطرات کم کرنے کے ساتھ متاثرین کو بہتری کے زیادہ سے زیادہ مواقع دیتا ہے؛ یہ ایک فن ہے اور اس میں مشاہدے، مطالعے اور تجربے سے ماہر افراد کام کرتے ہیں؛ منصوبہ ایک دستاویزی پروگرام ہے جس میں سانحے کے دوران اور بعد کی تمام سرگرمیاں شامل ہیں۔","ٹیم کی سرگرمیاں: فوراً ذمہ داری اور مقام سنبھالنا، حقائق کا تعین، اپنا مؤقف بیان کرنا اور مسئلے پر قابو پانا؛ ہر رکن کا کردار طے؛ ذمہ دار لوگوں کی موجودگی تاکہ موقع پر احکامات اور رقم مل سکے؛ کیا، کب، کیوں، کہاں، کس کے لیے اور کون — کے جواب منصوبے میں ہوں۔","نعرہ \"تیار رہنا\": ہر قسم کے سانحے کی تیاری؛ کمیونٹی، سول ڈیفنس، این جی اوز اور رضاکاروں کی شمولیت؛ متاثرین کی بحالی کا منصوبہ۔"]},{"q":[["civ12-ch8-exercise-2",22]],"s":["کمیونٹی سروس سے مراد عوامی خدمت یا عطیات پر مبنی سرگرمی ہے جس سے کمیونٹی کو فائدہ ہو؛ یہ عموماً رضاکاروں کا کام ہے، مگر بعض لوگ معاوضہ لیتے یا پابند کیے جاتے ہیں (بعض حکومتیں شہریوں پر لازمی کرتی ہیں؛ فوجی ملازمین اور سکولوں کے طلبہ تربیت کے طور پر)۔","ہر شہری کی اخلاقی ذمہ داری ہے کہ اپنی کمیونٹی کی خدمت کے لیے آگے آئے؛ صرف اپنا پیٹ بھرنا اچھی شہریت کے لیے کافی نہیں۔","مثالیں: بچوں کو پڑھانا، کم آمدنی والوں کے لیے سادہ مکانات بنانا، بزرگوں کی خدمت، جانوروں کے لیے پناہ گاہیں، آگ بجھانا، ہنگامی خدمات اور علاقے کی خوبصورتی (صفائی مہم، شجرکاری)۔","محرکات: آخرت کی کامیابی، اللہ کی رضا، حقیقی خوشی، اجتماعی زندگی میں سکون، انسانی خدمت کا جذبہ اور روحانی نجات؛ بعض کو سزا کے طور پر بھی لگایا جاتا ہے۔","فوائد: نئے لوگوں کو سیکھنے کا موقع، کمیونٹی کے مسائل کا ادراک، بہتر ماحول اور سماجی ہم آہنگی؛ اس کے فوائد ہی فوائد ہیں، نقصان کوئی نہیں۔"]}],"activities":[{"q":[["civ12-ch8-exercise-2",24]],"s":["ٹی وی کے لیے عوامی خدمت کا اعلان تیار کرنا — مثال: موضوع \"ٹریفک قوانین کی پابندی\"، دورانیہ 30 سیکنڈ (60–75 الفاظ)۔","اسکرپٹ دو کالموں میں: بائیں — مناظر (سگنل توڑتی گاڑی، حادثہ، ہیلمٹ پہنے موٹر سائیکل سوار)، کیمرہ زاویے، آوازیں؛ دائیں — مکالمہ: \"ایک لمحے کی جلدی، عمر بھر کا پچھتاوا۔ سگنل کا احترام کریں، ہیلمٹ پہنیں، رفتار کم رکھیں۔\" آخر میں ادارے کا نام اور ہیلپ لائن نمبر؛ واضح آواز اور سادہ الفاظ۔"]},{"q":[["civ12-ch8-exercise-2",25]],"s":["دستخطی مہم: کسی قومی یا عالمی مسئلے کا انتخاب (مثلاً پلاسٹک تھیلوں پر پابندی، بچوں کی مزدوری کا خاتمہ، مسئلۂ کشمیر)۔","مراحل: مختصر درخواست/یادداشت لکھنا؛ دستخطی فارم (نام، پتا، دستخط) تیار کرنا؛ دو تین کارکنوں کی ٹیمیں بنا کر سکول، بازار اور پارکوں میں لوگوں کو آمنے سامنے سمجھا کر دستخط لینا؛ آخر میں دستخط شدہ دستاویز متعلقہ ادارے کو پیش کرنا۔"]},{"q":[["civ12-ch8-exercise-2",26]],"s":["انٹرنیٹ پر دستخطی مہم: آن لائن پٹیشن ویب سائٹ یا گوگل فارم پر درخواست بنانا؛ سوشل میڈیا، ای میل اور میسجنگ گروپوں کے ذریعے لنک پھیلانا؛ مختصر ویڈیو یا پوسٹر سے مقصد سمجھانا؛ دستخطوں کی تعداد کی تازہ صورتحال بتانا؛ آخر میں نتائج متعلقہ حکام کو بھیجنا۔ ذاتی معلومات کی رازداری کا خیال رکھا جائے۔"]}]}}});
